from typing import List

def longest_bitonic_length(nums: List[int]) -> int:
    n = len(nums)
    if n <= 1:
        return n

    # Initialize left and right arrays to store the maximum length of increasing subsequence ending at each index
    left = [1] * n
    right = [1] * n

    # Build the left array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                left[i] = max(left[i], left[j] + 1)

    # Build the right array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                right[i] = max(right[i], right[j] + 1)

    # The length of the longest bitonic sequence is the sum of the maximum lengths from both directions minus one (to avoid double-counting the element itself)
    return max(max(left), max(right)) - 1
```

