from typing import List

def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def dfs(x, y, visited):
        if grid[x][y] == 'X':
            return float('inf')

        if (x, y) in visited:
            return float('inf')

        visited.add((x, y))

        min_steps = float('inf')
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            min_steps = min(min_steps, 1 + dfs(nx, ny, visited))

        visited.remove((x, y))
        return min_steps

    start_x, start_y = next((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 'S')
    end_x, end_y = next((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 'E')

    return dfs(start_x, start_y, set())
