    max_lengths = [max(len(row[i]) for i in range(len(row))) for row in rows]
    formatted_rows = []
    for row in rows:
        formatted_row = ""
        for i, cell in enumerate(row):
            if aligns[i] == 'l':
                formatted_row += cell.ljust(max_lengths[i])
            elif aligns[i] == 'r':
