def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    def multiply_matrices(a: List[List[int]], b: List[List[int]]) -> List[List[int]]:
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += (a[i][k] * b[k][j]) % mod
        return result

    def power_matrix(base: List[List[int]], exponent: int, modulo: int) -> List[List[int]]:
        if exponent == 1:
            return base
        elif exponent % 2 == 0:
            half_power = power_matrix(base, exponent // 2, modulo)
            return multiply_matrices(half_power, half_power, modulo)
        else:
            return multiply_matrices(base, power_matrix(base, exponent - 1, modulo), modulo)

    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
