def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    # Initialize distances and paths
    distances = {node: float('inf') for node in set(edge[0] for edge in edges)}
    distances[start] = 0
    paths = {node: [] for node in set(edge[0] for edge in edges)}

    # Priority queue to store nodes to visit
    import heapq
    heap = [(0, start)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        if current_node == goal:
            return (current_distance, paths[current_node])

        for neighbor, weight in edges:
            if neighbor == current_node:
                continue
            new_distance = current_distance + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                paths[neighbor] = paths[current_node].copy()
                paths[neighbor].append(neighbor)
                heapq.heappush(heap, (new_distance, neighbor))

    return None
