def mean_and_median(numbers: List[float]) -> Tuple[float, float]:
    if len(numbers) == 0:
        raise ValueError("List is empty")

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 1:
        # If odd number of elements, return the middle element
        return sorted_numbers[n // 2], round(sorted_numbers[n // 2])
    else:
        # If even number of elements, return the average of the two middle elements
        mid1 = sorted_numbers[n // 2 - 1]
        mid2 = sorted_numbers[n // 2]
        return (mid1 + mid2) / 2, round((mid1 + mid2) / 2)
