def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # If both numbers are less than or equal to 31, use Brian Kernighan's algorithm
    if lo <= 31 and hi <= 31:
        return bin(hi).count('1') - bin(lo - 1).count('1')

    # If one number is greater than 31, calculate the total set bits in the range
    total_set_bits = 0
    for i in range(lo, hi + 1):
        total_set_bits += bin(i).count('1')

    return total_set_bits
