    # Verificar si las matrices son compatibles para multiplicación
    if len(a[0]) != len(b):
        raise ValueError("Las matrices no son compatibles para multiplicación")

    # Inicializar la matriz resultante con ceros
    result = [[0 for _ in range(len(b[0]))] for _ in range(len(a))]

    # Realizar la multiplicación matricial
    for i in range(len(a)):
        for j in range(len(b[0])):
            for k in range(len(b)):
                result[i][j] += a[i][k] * b[k][j]

    return result
