def is_anagram(s1: str, s2: str) -> bool:
    # Convertir ambas cadenas a minúsculas y eliminar espacios
    s1 = s1.lower().replace(" ", "")
    s2 = s2.lower().replace(" ", "")

    # Comprobar si ambas cadenas tienen la misma longitud
    if len(s1) != len(s2):
        return False

    # Crear dos diccionarios para contar las frecuencias de cada letra
    freq_s1 = {}
    freq_s2 = {}

    # Contar las frecuencias de cada letra en s1
    for char in s1:
        if char in freq_s1:
            freq_s1[char] += 1
        else:
            freq_s1[char] = 1

    # Contar las frecuencias de cada letra en s2
    for char in s2:
        if char in freq_s2:
            freq_s2[char] += 1
        else:
            freq_s2[char] = 1

    # Comparar los dos diccionarios
    return freq_s1 == freq_s2
