def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    rows = len(matrix)
    cols = len(matrix[0])
    result = []
    i, j = 0, 0
    direction = 'right'

    while True:
        result.append(matrix[i][j])

        # Move to the next position based on the current direction
        if direction == 'right':
            if j + 1 < cols and matrix[i][j + 1] != 0:
                j += 1
            else:
                direction = 'down'
                i += 1
        elif direction == 'down':
            if i + 1 < rows and matrix[i + 1][j] != 0:
                i += 1
            else:
                direction = 'left'
                j -= 1
        elif direction == 'left':
            if j - 1 >= 0 and matrix[i][j - 1] != 0:
                j -= 1
            else:
                direction = 'up'
                i -= 1
        elif direction == 'up':
            if i - 1 >= 0 and matrix[i - 1][j] != 0:
                i -= 1
            else:
                break

    return result
