import math

def token_entropy(tokens: list[str]) -> float:
    if not tokens:
        return 0.0

    frequency_dict = {}
    for token in tokens:
        if token in frequency_dict:
            frequency_dict[token] += 1
        else:
            frequency_dict[token] = 1

    total_tokens = len(tokens)
    entropy = 0.0
    for freq in frequency_dict.values():
        probability = freq / total_tokens
        entropy -= probability * math.log2(probability)

    return round(entropy, 3)
