def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Find increasing subsequence ending at each index
    increasing = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # Find decreasing subsequence starting from each index
    decreasing = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # The length of the longest bitonic sequence is the maximum value in the product of these two sequences
    return max([increasing[i] * decreasing[i] for i in range(n)])

