def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Calculate the number of set bits in the highest bit of both numbers
    max_bit = max(hi.bit_length(), lo.bit_length())

    # Count the set bits in the highest bit
    set_bits_in_max_bit = max_bit - (max_bit & (max_bit - 1))

    # Calculate the number of set bits in the range from lo to hi
    set_bits_in_range = 0

    for i in range(max_bit):
        if (hi >> i) & 1 and (lo >> i) & 1:
            set_bits_in_range += 1

    return set_bits_in_range + set_bits_in_max_bit

def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Calculate the number of set bits in the highest bit position
    max_bit = 31 - (hi.bit_length() - 1)

    # Count the set bits in the range [lo, hi]
    count = 0
    for i in range(max_bit + 1):
        mask = 1 << i
        if lo & mask and hi & mask:
            count += 1

    return count

