def parse_kv_pairs(text: str) -> dict[str, str]:
    if not text:
        return {}

    kv_pairs = []
    current_key = None

    for char in text:
        if char == '=':
            if current_key is not None:
                kv_pairs.append((current_key, text[current_key + 1:]))
