def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    row_index = 0
    col_index = 0
    direction = 'right'

    while True:
        # Append current element to result
        result.append(matrix[row_index][col_index])

        # Move in the current direction
        if direction == 'right':
            if col_index < len(matrix[0]) - 1:
                col_index += 1
            else:
                row_index += 1
                direction = 'down'
        elif direction == 'down':
            if row_index < len(matrix) - 1:
                row_index += 1
            else:
                col_index -= 1
                direction = 'left'
        elif direction == 'left':
            if col_index > 0:
                col_index -= 1
            else:
                row_index -= 1
                direction = 'up'
        elif direction == 'up':
            if row_index > 0:
                row_index -= 1
            else:
                col_index += 1
                direction = 'right'

        # Check if we have reached the end of the matrix
        if row_index >= len(matrix) or col_index >= len(matrix[0]):
            break

    return result
