    if not nums:
        return 0

    n = len(nums)
    inc = [1] * n
    dec = [1] * n

    # Find the length of the longest increasing subsequence ending at each index
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Find the length of the longest decreasing subsequence starting at each index
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The length of the longest bitonic subsequence is the maximum value in the product of inc and dec arrays
    return max([inc[i] * dec[i] for i in range(n)])
