def derive_key(passphrase: str, salt: bytes) -> bytes:
    # Convert passphrase to bytes and ensure it's not empty
    if not passphrase:
        raise ValueError("Passphrase cannot be empty")

    # Ensure salt is at least 8 bytes long
    if len(salt) < 8:
