from typing import List

def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    increasing = [1] * n
    decreasing = [1] * n

    # Fill increasing array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # Fill decreasing array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # Find the maximum length of bitonic sequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, increasing[i] + decreasing[i] - 1)

    return max_length
```

