from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)

    # Build the graph from the given edges
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, visited, path_length):
        if node == target:
            return 1

        visited.add(node)

        paths_count = 0
        for neighbor in graph[node]:
            if neighbor not in visited:
                paths_count += dfs(neighbor, visited, path_length + 1)

        visited.remove(node)
        return paths_count

    visited = set()
    return dfs(source, visited, 0)
