from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(board: List[List[bool]], row: int, col: int) -> bool:
        # Check this row on left side
        for i in range(col):
            if board[row][i]:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j]:
                return False

        return True

    def solve_n_queens_util(board: List[List[bool]], col: int) -> bool:
        # base case: If all queens are placed
        if col >= n:
            return True

        # Consider this column and try placing queen in all rows one by one
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = True

                # recur to place rest of the queens
                if solve_n_queens_util(board, col + 1):
                    return True

                # If placing queen in board[i][col] doesn't lead to a solution,
                # then remove queen from board[i][col]
                board[i][col] = False

        # If the queen cannot be placed in any row in this column, return false
        return False

    # Initialize the chessboard with zeros
    board = [[False for _ in range(n)] for _ in range(n)]

    # Call the recursive function to solve the N-Queens problem
    if not solve_n_queens_util(board, 0):
        return 0

    # Count the number of solutions
    return sum(1 for row in board for cell in row if cell)
