def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def bfs(start):
        queue = deque([(start, 0)])
        visited = set()
        while queue:
            node, distance = queue.popleft()
            if node == target:
                return distance
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, distance + 1))
        return -1

    shortest_path_length = bfs(source)
    if shortest_path_length == -1:
        return 0
    elif source == target:
        return 1
    else:
        return shortest_path_length
