import operator
from collections import deque

def evaluate_expression(expression: str) -> float:
    operators = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv, '**': operator.pow}
    stack = deque()
    num = ''

    for char in expression:
        if char.isdigit():
            num += char
        elif char == '(':
            stack.append(num)
            num = ''
        elif char in operators or char == ')':
            while stack and stack[-1] != '(':
                right = float(stack.pop())
                left = float(stack.pop())
                op = stack.pop()
                result = operators[op](left, right)
                stack.append(result)
            if char == ')':
                num = stack.pop()
            else:
                stack.append(float(num))
                num = ''

        if char == ' ' and num:
            stack.append(float(num))
            num = ''

    return float(stack[0])
