def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(row: int, col: int) -> bool:
        for r, c in blocked:
            if row == r or col == c or abs(row - r) == abs(col - c):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(row, col):
                blocked.append((row, col))
                count += backtrack(row + 1)
                blocked.pop()

        return count

    return backtrack(0)
