def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    def multiply_matrices(a: List[List[int]], b: List[List[int]]) -> List[List[int]]:
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += (a[i][k] * b[k][j]) % mod
        return result

    def modular_exponentiation(base: List[List[int]], exponent: int, modulus: int) -> List[List[int]]:
        if exponent == 0:
            return [[1] * len(base[0])]  # Identity matrix
        elif exponent % 2 == 0:
            half_result = modular_exponentiation(base, exponent // 2, modulus)
            return multiply_matrices(half_result, half_result, modulus)
        else:
            return multiply_matrices(base, modular_exponentiation(base, exponent - 1, modulus), modulus)

    return modular_exponentiation(matrix, exp, mod)
