def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += a[i][k] * b[k][j]
                    result[i][j] %= mod
        return result

    def matrix_exponentiation(matrix: list[list[int]], exponent: int, mod: int) -> list[list[int]]:
        if exponent == 0:
            return [[1] * len(matrix[0])] * len(matrix)
        elif exponent % 2 == 0:
            half_matrix = matrix_exponentiation(matrix, exponent // 2, mod)
            return multiply_matrices(half_matrix, half_matrix, mod)
        else:
            return multiply_matrices(matrix, matrix_exponentiation(matrix, exponent - 1, mod), mod)

    return matrix_exponentiation(matrix, exp, mod)
