from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    distances = [-1] * n

    def dfs(node):
        if node == target:
            return 1

        if visited[node]:
            return 0

        visited[node] = True

        for neighbor in graph[node]:
            if distances[neighbor] == -1:
                distances[neighbor] = distances[node] + 1
                paths = dfs(neighbor)
                if paths > 0:
                    return paths

        return 0

    distances[source] = 0
    return dfs(source)
