def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize distance array with infinity except for the source node
    dist = [float('inf')] * n
    dist[source] = 0

    # Priority queue to store nodes based on their distance from the source
    pq = [(0, source)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        # If the current distance is greater than the known distance, skip this node
        if current_distance > dist[current_node]:
            continue

        # Explore all neighbors of the current node
        for neighbor in adj_list[current_node]:
            new_distance = current_distance + 1

            # If a shorter path is found, update the distance and add the neighbor to the priority queue
            if new_distance < dist[neighbor]:
                dist[neighbor] = new_distance
                heapq.heappush(pq, (new_distance, neighbor))

    # Check if the target node is reachable
    if dist[target] == float('inf'):
        return 0
    else:
        # Count the number of shortest paths to the target node
        return sum(1 for d in dist if d == dist[target])

