def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize distances and parent arrays
    dist = [float('inf')] * n
    parent = [-1] * n
    dist[source] = 0

    # Perform BFS to find shortest paths
    queue = deque([source])
    while queue:
        current = queue.popleft()
        for neighbor in adj_list[current]:
            if dist[neighbor] > dist[current] + 1:
                dist[neighbor] = dist[current] + 1
                parent[neighbor] = current
                queue.append(neighbor)

    # Check if target is reachable
    if dist[target] == float('inf'):
        return 0

    # Count distinct shortest paths using DFS
    def dfs(node):
        visited[node] = True
        count = 1
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                count += dfs(neighbor)
        return count

    visited = [False] * n
    return dfs(target)

