import re

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Expression cannot be empty")

    # Remove spaces from the expression
    expression = expression.replace(" ", "")

    # Check for balanced parentheses
    if "(" not in expression or ")" not in expression:
        raise ValueError("Parentheses are not balanced")

    # Define the precedence and associativity of operators
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '**': 3
    }
    associativity = {
        '+': 'left',
        '-': 'left',
        '*': 'left',
        '/': 'left',
        '**': 'right'
    }

    # Split the expression into tokens
    tokens = re.findall(r'\d+(\.\d+)?|\+|-|\*|/|\^|\(|\)', expression)

    # Evaluate the expression using the Shunting Yard algorithm
    output_queue = []
    operator_stack = []

    for token in tokens:
        if token.isdigit() or '.' in token:
            output_queue.append(float(token))
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            operator_stack.pop()
        else:
            while operator_stack and operator_stack[-1] != '(' and (
                    precedence[token] > precedence[operator_stack[-1]] or
                    (precedence[token] == precedence[operator_stack[-1]] and associativity[token] == 'left')
            ):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)

    while operator_stack:
        output_queue.append(operator_stack.pop())

    # Evaluate the postfix expression
    stack = []
    for token in output_queue:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Cannot divide by zero")
                stack.append(a / b)
            elif token == '^':
                stack.append(a ** b)

    return stack[0]
