def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1

    queue = [(start_pos, 0)]
    visited = set()

    while queue:
        pos, moves = queue.pop(0)

        if pos == end_pos:
            return moves

        x, y = pos

        # Check all four possible directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), moves + 1))

    return -1
