from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extracting moduli and remainders from the list of tuples
    moduli = [c[1] for c in congruences]
    remainders = [c[0] for c in congruences]

    # Finding the product of all moduli
    product_moduli = reduce(lcm, moduli)

    # Calculating the modular inverses of remainders modulo each modulus
    inverses = {r: pow(r, -1, m) for r, m in zip(remainders, moduli)}

    # Solving the system of linear congruences using the Chinese Remainder Theorem
    result_x = sum((remainder * inverse * product_moduli // modulus) for remainder, inverse, modulus in zip(remainders, inverses.values(), moduli))
    result_x %= product_moduli

    # Ensuring the result is within the range [0, product_moduli)
    result_x += product_moduli

    return (result_x, product_moduli)
