from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders
    mods = [c[1] for c in congruences]
    remainders = [c[0] for c in congruences]

    # Calculate LCM of all moduli
    lcm_mods = reduce(lcm, mods)

    # Create a matrix to store coefficients
    matrix = [[0]*len(mods) for _ in range(len(mods))]
    for i in range(len(mods)):
        matrix[i][i] = 1

    # Fill the matrix with coefficients based on remainders
    for i in range(len(mods)):
        for j in range(i+1, len(mods)):
            matrix[j][i] = -remainders[j] * pow(remainders[i], -1, mods[i]) % mods[j]

    # Perform Gaussian elimination
    for i in range(len(matrix)):
        pivot = matrix[i][i]
        for j in range(i+1, len(matrix)):
            factor = matrix[j][i] / pivot
            for k in range(len(matrix[i])):
                matrix[j][k] -= factor * matrix[i][k]

    # Back substitution to find the solution
    solution = [matrix[i][-1] for i in range(len(matrix)-1, -1, -1)]
    x = solution[0]
    L = lcm_mods

    # Check if the solution is valid
    if any(x % m != r % m for r, m in congruences):
        return None

    return (x, L)
