from collections import defaultdict

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    graph = defaultdict(list)
    indegree = [0] * n

    for a, b in pairs:
        graph[a].append(b)
        indegree[b] += 1

    queue = []

    # Add nodes with zero indegree to the queue
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    topological_order = []

    while queue:
        node = queue.pop(0)
        topological_order.append(node)

        for neighbor in graph[node]:
            indegree[neighbor] -= 1

            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return topological_order

