            for c in range(len(grid[0])):
                if grid[r][c] >= 4:
                    # Reduce the sand at this cell by 4
                    grid[r][c] -= 4

                    # Spread the sand to neighboring cells
                    spread_sand(new_grid, r, c)

        # If no more sand is added, break the loop
        if all(sum(row) == 0 for row in new_grid):
