import operator

def evaluate_expression(expression: str) -> float:
    try:
        # Define the operators and their corresponding functions
        ops = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow,
            '-': lambda x: -x
        }

        # Split the expression into tokens
        tokens = expression.replace(' ', '').split()

        # Initialize the stack for operands
        stack = []

        # Process each token in the expression
        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token in ops:
                right = stack.pop()
                left = stack.pop()
                result = ops[token](left, right)
                stack.append(result)
            else:
                raise ValueError(f"Invalid token: {token}")

        # The final result should be the only element left in the stack
        return stack[0]

    except ZeroDivisionError:
        raise ValueError("Cannot divide by zero")
    except ValueError as e:
        raise ValueError(e)

# Example usage:
print(evaluate_expression("3 + 4 * 2"))  # Output: 11.0
print(evaluate_expression("(3 + 4) * 2"))  # Output: 14.0
