from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract coefficients and moduli from the congruences
    A = [c[0] for c in congruences]
    M = [c[1] for c in congruences]

    # Calculate the product of all moduli
    N = 1
    for m in M:
        N *= m

    # Calculate the partial products
    P = []
    for i in range(len(M)):
        P.append(N // M[i])

    # Calculate the modular inverses
    invs = []
    for p in P:
        inv = pow(p, -1, M[i])
        invs.append(inv)

    # Solve the system of linear equations
    x = 0
    for i in range(len(A)):
        x += A[i] * invs[i] * M[i]

    # Reduce x modulo N to get the solution within the range [0, N-1]
    x %= N

    # Check if the solution is valid
    for i in range(len(M)):
        if x % M[i] != A[i]:
            return None

    return (x, N)
