def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])

    # Create a copy of the grid to avoid modifying the original
    new_grid = [row[:] for row in grid]

    # Iterate over each cell in the grid
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] >= 4:
                # Reduce the current cell's value by 4
                grid[r][c] -= 4

                # Distribute the remaining sand to neighboring cells
                if r > 0:
                    new_grid[r - 1][c] += 1
                if r < rows - 1:
                    new_grid[r + 1][c] += 1
                if c > 0:
                    new_grid[r][c - 1] += 1
                if c < cols - 1:
                    new_grid[r][c + 1] += 1

    return new_grid
