from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if len(congruences) == 0:
        return (0, 1)

    # Extract moduli and remainders from the congruences
    moduli = [c[1] for c in congruences]
    remainders = [c[0] for c in congruences]

    # Calculate the product of all moduli
    M = reduce(lcm, moduli)

    # Calculate the multiplicative inverse of each remainder modulo its corresponding modulus
    inverses = [(pow(r, -1, m), m) for r, m in zip(remainders, moduli)]

    # Solve the system of linear equations using the Chinese Remainder Theorem
    x = sum(r * inv * M // m for r, inv, m in inverses) % M

    # Check if the solution satisfies all congruences
    if any(x != r % m for r, _ in congruences):
        return None

    return (x, M)
