    def topple(r, c):
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] <= 3:
            return
        grid[r][c] -= 4
        for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                grid[nr][nc] += 1

    while True:
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] > 3:
                    topple(r, c)
                    changed = True
        if not changed:
            break
    return grid
