from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract all unique moduli and their corresponding remainders
    moduli = set()
    remainders = []
    for r, m in congruences:
        moduli.add(m)
        remainders.append(r % m)

    # Calculate the product of all moduli
    L = lcm(*moduli)

    # Solve each congruence individually
    solutions = {}
    for r, m in congruences:
        # Find the modular inverse of m modulo L
        inv_m = pow(m, -1, L)

        # Solve the congruence x % m = r % m
        x = (r * inv_m) % L

        solutions[m] = x

    # Check if there is a solution that satisfies all congruences
    for i in range(len(remainders)):
        if solutions[moduli[i]] != remainders[i]:
            return None

    return (solutions[moduli[0]], L)
