def expand_template(template: str, values: dict[str, str]) -> str:
    result = ""
    i = 0
    while i < len(template):
        if template[i] == "{{":
            j = i + 1
            while j < len(template) and template[j] != "}}":
                j += 1
            if j >= len(template):
                raise ValueError("Unmatched braces in template")
            placeholder = template[i+2:j]
            if placeholder in values:
                result += values[placeholder]
            else:
                result += placeholder
            i = j + 1
        else:
            result += template[i]
            i += 1
    return result
