from typing import List, Tuple

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract all unique moduli and their corresponding remainders
    moduli = set()
    remainders = set()
    for r, m in congruences:
        moduli.add(m)
        remainders.add(r % m)

    # Check if there is at least one remainder that cannot be satisfied by any modulus
    if len(remainders) != len(moduli):
        return None

    # Calculate the minimum common multiple of all moduli
    lcm = 1
    for m in moduli:
        lcm = lcm * m // gcd(lcm, m)

    # Find the solution to the system of congruences
    x = 0
    for r, m in congruences:
        x += r * pow(lcm // m, -1, m)

    # Normalize the solution to be within the range [0, lcm-1]
    x %= lcm

    return (x, lcm)
