def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extracting coefficients and moduli from each congruence
    A = [c[0] for c in congruences]
    M = [c[1] for c in congruences]

    # Finding the least common multiple of all moduli
    L = lcm(*M)

    # Solving the system of linear congruences using the Chinese Remainder Theorem
    x = 0
    for i in range(len(A)):
        Mi = L // M[i]
        xi = pow(Mi, -1, M[i])
        x = (x + A[i] * Mi * xi) % L

    return (x, L)

