def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])

    while True:
        # Check for any cell with more than 3 grains
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] > 3:
                    # Topple the cell
                    grid[r][c] -= 4
                    # Distribute the grains to neighbors
                    if r > 0:
                        grid[r-1][c] += 1
                    if r < rows - 1:
                        grid[r+1][c] += 1
                    if c > 0:
                        grid[r][c-1] += 1
                    if c < cols - 1:
                        grid[r][c+1] += 1
                    changed = True

        # If no changes were made, break the loop
        if not changed:
            break

    return grid
