from typing import List, Tuple

def lex_topological_order(n: int, pairs: List[Tuple[int, int]]) -> List[int]:
    if n == 0:
        return []

    # Inicializar el grafo y el vector de visitados
    graph = [[] for _ in range(n)]
    visited = [False] * n
    topological_order = []

    # Construir el grafo
    for a, b in pairs:
        graph[a].append(b)

    # Función de recorrido DFS
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        topological_order.append(node)

    # Recorrer el grafo desde nodos sinadyacentes
    for i in range(n):
        if not visited[i]:
            dfs(i)

    # Si hay un ciclo, devolver una lista vacía
    if len(topological_order) != n:
        return []

    return topological_order[::-1]
