def convert_base(number: str, from_base: int, to_base: int) -> str:
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    if number[0] == '-':
        sign = '-'
        number = number[1:]
    else:
        sign = ''

    if not all(c in digits for c in number):
        raise ValueError("Invalid digit in number")

    decimal_number = 0
    power = 0

    for i in range(len(number) - 1, -1, -1):
        digit = number[i]
        if digit.isdigit():
            decimal_number += int(digit) * (from_base ** power)
        else:
            decimal_number += digits.index(digit.lower()) + 10 * (from_base ** power)

        power += 1

    if decimal_number == 0:
        return '0'

    result = ''
    while decimal_number > 0:
        remainder = decimal_number % to_base
        result = digits[remainder] + result
        decimal_number //= to_base

    return sign + result
