from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = set()

        while queue:
            x, y, steps = queue.popleft()

            if (x, y) == end:
                return steps

