from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a set of all guests for quick lookup
    guests_set = set(guests)

    def is_valid(arrangement):
        for a, b in conflicts:
            if arrangement.index(a) == arrangement.index(b):
                return False
        return True

    def backtrack(start, current_arrangement):
        if start == len(guests):
            if is_valid(current_arrangement):
                arrangements.append(list(current_arrangement))
            return

        for guest in guests_set - set(current_arrangement):
            current_arrangement.append(guest)
            backtrack(start + 1, current_arrangement)
            current_arrangement.pop()

    arrangements = []
    backtrack(0, [])
    return arrangements
