def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a dictionary to store the positions of each guest
    guest_positions = {guest: i for i, guest in enumerate(guests)}

    # Sort the guests based on their positions and then by their names
    sorted_guests = sorted(guests, key=lambda x: (guest_positions[x], x))

    # Initialize the result with the first guest's position
    result = [[sorted_guests[0]]]

    # Iterate over the remaining guests
    for guest in sorted_guests[1:]:
        # Find the position where the current guest can be seated without any conflict
        new_position = None
        for pos in range(len(result[-1])):
            if all(not (result[-1][pos] == other or (result[-1][pos][0] == other[0] and result[-1][pos][1] == other[1])) for other in conflicts):
                new_position = pos
                break

        # If no valid position is found, add the guest at the end of the last row
        if new_position is None:
            result[-1].append([guest])
        else:
            result.append([result[-1][new_position], [guest]])

    return result
