def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a dictionary to store the availability of each guest
    guest_availability = {guest: True for guest in guests}

    # Remove guests who cannot be seated due to conflicts
    for conflict in conflicts:
        if conflict[0] in guest_availability and conflict[1] in guest_availability:
            guest_availability[conflict[0]] = False
            guest_availability[conflict[1]] = False

