def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or not isinstance(from_base, int) or not isinstance(to_base, int):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    if '-' in number:
        sign = True
        number = number[1:]
    else:
        sign = False

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    result = ''

    for digit in reversed(number):
        if digit.isdigit():
            value = int(digit)
        else:
            value = digits.index(digit.lower())

        if value >= from_base:
            raise ValueError(f"Digit {digit} is out of range for base {from_base}")

        result = digits[value] + result

    if sign:
        result = '-' + result

    return result
