import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    if not url.startswith(('http://', 'https://')):
        return False

    host = re.search(r'(?<=:\/\/)[^\/]+', url).group()

    if '@' in host:
        return False

    domain_parts = host.split('.')
    if len(domain_parts) < 2:
        return False

    if '.' in domain_parts[-1]:
        domain_parts[-1] = domain_parts[-1].split('.')[0]

    if domain_parts[0] == 'localhost':
        return True

    for allowed_host in allowed_hosts:
        allowed_domain_parts = allowed_host.split('.')
