from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")
    if n == 0:
        return start

    # Convert holidays to datetime objects for easier comparison
    holidays_dates = [datetime.strptime(holiday, "%Y-%m-%d") for holiday in holidays]

    # Adjust for negative days by moving backwards from the end of the range
    if n < 0:
        while n < 0:
            current_date = start_date - timedelta(days=1)
            if current_date not in holidays_dates and current_date.weekday() < 5:
                start_date = current_date
                n += 1
    else:
        # Adjust for positive days by moving forwards
        while n > 0:
            current_date = start_date + timedelta(days=1)
            if current_date not in holidays_dates and current_date.weekday() < 5:
                start_date = current_date
                n -= 1

    return start_date.strftime("%Y-%m-%d")
