def stabilize_sandpile(grid):
    if not grid:
        return []

    def count_neighbors(r, c):
        neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
        return sum(1 for nr, nc in neighbors if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] >= 4)

    def spread_grains(r, c):
        if grid[r][c] >= 4:
            grid[r][c] -= 4
            for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    grid[nr][nc] += 1

    while True:
        new_grid = [[0] * len(row) for row in grid]
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                new_grid[r][c] = count_neighbors(r, c)
        spread_grains(*find_max_grain_position(new_grid))
