def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def propagate_grains(r, c):
        nonlocal grid
        if grid[r][c] >= 4:
            grid[r][c] -= 4
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
