def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a set of all guests to check for conflicts easily
    guests_set = set(guests)

    def is_valid(arrangement):
        for i in range(len(arrangement)):
            for j in range(i + 1, len(arrangement)):
                if (arrangement[i], arrangement[j]) in conflicts or (arrangement[j], arrangement[i]) in conflicts:
                    return False
        return True

    def backtrack(start, current_arrangement):
        if start == len(guests):
            if is_valid(current_arrangement):
                arrangements.append(current_arrangement[:])
            return

        for guest in guests[start:]:
            if guest not in current_arrangement and guest not in guests_set - {current_arrangement[-1]} if current_arrangement else True:
                current_arrangement.append(guest)
                backtrack(start + 1, current_arrangement)
                current_arrangement.pop()

    arrangements = []
    backtrack(0, [])
    arrangements.sort(key=lambda x: x[0])
    return arrangements
