        while n > 0:
            start_date += timedelta(days=1)
            if start_date.weekday() >= 5 or start_date.strftime("%Y-%m-%d") in holidays:
                start_date -= timedelta(days=1)

    return start_date.strftime("%Y-%m-%d")
