from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a set of all guests for quick lookup
    guests_set = set(guests)

    def backtrack(arrangement):
        if len(arrangement) == len(guests):
            return [arrangement[:]]

        results = []
        for guest in guests_set - set(arrangement):
            if not any((guest, other) in conflicts or (other, guest) in conflicts for other in arrangement):
                new_arrangement = arrangement + [guest]
                results.extend(backtrack(new_arrangement))

        return results

    return backtrack([])
