def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Verificar el protocolo HTTP/HTTPS
    if not url.startswith(('http://', 'https://')):
        return False

    # Eliminar el protocolo y el dominio si es HTTPS
    if url.startswith('https://'):
        url = url[8:]

    # Extraer el dominio y el subdomino
    domain, *subdomains = url.split('.')

    # Convertir todo a minúsculas
    domain = domain.lower()
    for i in range(len(subdomains)):
        subdomains[i] = subdomains[i].lower()

    # Eliminar el punto final si existe
    if domain.endswith('.'):
        domain = domain[:-1]

    # Comprobar si el dominio o subdomino está en la lista de permitidos
    for allowed_host in allowed_hosts:
        allowed_host = allowed_host.lower()
        if allowed_host == domain or any(allowed_host == '.'.join([domain, subdomain]) for subdomain in subdomains):
            return True

    return False

