from typing import List, Tuple

def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Sort busy intervals by their start times
    busy.sort(key=lambda x: x[0])

    # Initialize variables to track the current gap
    current_gap = None
    free_gaps = []

    for start, end in busy:
        if current_gap is None:
            current_gap = (start, end)
        elif end < current_gap[1]:
            # Extend the current gap
            current_gap = (current_gap[0], max(current_gap[1], end))
        else:
            # End of the current gap
            if current_gap[1] - current_gap[0] >= min_len:
                free_gaps.append((current_gap[0], current_gap[1]))
