def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Sort guests to ensure consistent ordering for comparison
    guests.sort()

    def is_valid(arrangement):
        for i in range(len(arrangement) - 1):
            if (arrangement[i], arrangement[i + 1]) in conflicts or (arrangement[i + 1], arrangement[i]) in conflicts:
                return False
        return True

    def backtrack(start, current_arrangement):
        if start == len(guests):
            if is_valid(current_arrangement):
                arrangements.append(current_arrangement[:])
            return

        for i in range(start, len(guests)):
            current_arrangement.append(guests[i])
            backtrack(i + 1, current_arrangement)
            current_arrangement.pop()

    arrangements = []
    backtrack(0, [])
    return sorted(arrangements)
