def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number[0] == '-':
        raise ValueError("Invalid input")

    # Convert the input number to base 10
    num = int(number, from_base)

    # Handle the special case where the number is zero
    if num == 0:
        return '0'

    # Convert the base 10 number to the target base
    result = ''
    while num > 0:
        remainder = num % to_base
        if remainder >= 10:
            result = chr(remainder - 10 + ord('a')) + result
        else:
            result = str(remainder) + result
        num //= to_base

    # Add the '-' sign back if the original number was negative
    if number[0] == '-':
        result = '-' + result

    return result
