from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def count_neighbors(x, y):
        count = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and grid[nx][ny] == '#':
                count += 1
        return count

    def can_slide(x, y):
        neighbors = count_neighbors(x, y)
        if neighbors >= 2:
            return True
        return False

    start_x, start_y = None, None
    end_x, end_y = None, None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
            elif grid[i][j] == 'E':
                end_x, end_y = i, j

    if start_x is None or end_x is None:
        return -1

    queue = [(start_x, start_y)]
    visited = set()
    visited.add((start_x, start_y))
    steps = 0

    while queue:
        new_queue = []
        for x, y in queue:
            if (x, y) == (end_x, end_y):
                return steps
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
