import operator

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Split the expression into parts
        parts = expression.split()

        # Initialize the result to True
        result = True

        # Iterate over each part of the expression
        for part in parts:
            # Check if the part contains a variable or a literal
            if part.startswith('"') and part.endswith('"'):
                # Extract the variable name
                var_name = part[1:-1]
                # Get the corresponding value from the record
                value = record.get(var_name)
                # Convert the value to float if it's a number
                if isinstance(value, (int, float)):
                    value = float(value)
                # Evaluate the comparison using the appropriate operator
                if operator.not_(part.endswith('!')):
                    result &= operator.lt(value, float(part[2:-1]))
                else:
                    result &= operator.gt(value, float(part[2:-1]))
            elif part == 'and':
                result &= matches_filter(parts[parts.index(part) + 1], record)
            elif part == 'or':
                result |= matches_filter(parts[parts.index(part) + 1], record)
            elif part == 'not':
                result = not matches_filter(parts[parts.index(part) + 1], record)
            else:
                raise ValueError(f"Invalid expression: {expression}")

        return result
    except KeyError:
        raise ValueError("Variable not found in record")
    except ValueError as e:
        print(e)
        return False
