def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    if not results:
        return []

    # Initialize the league table with zeros for each team
    league_table = {team: [0, 0, 0] for team in set(home + away for home, away, _, _ in results)}

    # Populate the league table based on the results
    for home, away, home_goals, away_goals in results:
        if home_goals > away_goals:
            league_table[home][0] += 3
            league_table[away][2] -= 1
        elif home_goals < away_goals:
            league_table[away][0] += 3
            league_table[home][2] -= 1
        else:
            league_table[home][0] += 1
            league_table[away][0] += 1
            league_table[home][2] -= 1
            league_table[away][2] -= 1

    # Calculate goal difference and goals scored
    for team in league_table:
        league_table[team][1] = abs(league_table[team][0] - league_table[team][2])
        league_table[team][3] = sum([home_goals for home, away, home_goals, away_goals in results if home == team]) - sum([away_goals for home, away, home_goals, away_goals in results if away == team])

    # Sort the league table
    sorted_league_table = sorted(league_table.items(), key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]))

    return sorted_league_table

