def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting position of S
    start_row, start_col = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_row, start_col = i, j
                break

    if start_row is None or start_col is None:
        return -1  # No starting point found

    # Directions to move (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(row, col, steps):
        if row < 0 or row >= rows or col < 0 or col >= cols or grid[row][col] == '#':
            return float('inf')

        if grid[row][col] == 'E':
            return steps

        grid[row][col] = '#'  # Mark the cell as visited

        min_steps = float('inf')
        for dr, dc in directions:
            new_steps = dfs(row + dr, col + dc, steps + 1)
            min_steps = min(min_steps, new_steps)

        grid[row][col] = '.'  # Backtrack

        return min_steps

    min_steps = dfs(start_row, start_col, 0)
    return min_steps if min_steps != float('inf') else -1
