from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting position of S
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
                break

    # Directions to move up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def bfs(start_pos):
        queue = [(start_pos, 0)]
        visited = set()

        while queue:
            pos, steps = queue.pop(0)

            if pos == (rows - 1, cols - 1):
                return steps

            for dx, dy in directions:
                nx, ny = pos[0] + dx, pos[1] + dy

                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), steps + 1))

        return -1

    return bfs(start_pos)
