def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    jobs.sort(key=lambda x: (-x[2], -x[1]))  # Sort by profit in descending order and then by deadline in ascending order
    slots = [0] * 10  # Initialize slots with 0s
    scheduled = []

    for job_name, deadline, profit in jobs:
        free_slot = None
        for i in range(deadline - 1, -1, -1):
            if slots[i] == 0:
                free_slot = i
                break

        if free_slot is not None:
            slots[free_slot] = profit
            scheduled.append((job_name, free_slot + 1))

    return scheduled, [i for i in range(10) if slots[i] == 0]

