def parse_catalog(xml_text: str) -> list[dict]:
    if not xml_text:
        return []

    try:
        root = ET.fromstring(xml_text)
        books = []

        for book in root.findall('book'):
            id_ = book.get('id', '')
            title = book.find('title').text or ''
            author = book.find('author').text or ''

