    if len(matrix) == 0:
        return matrix

    n = len(matrix)

    # Create a new matrix to store the rotated result
    rotated_matrix = [[0] * n for _ in range(n)]

    # Iterate over each ring of the matrix
    for i in range(n // 2):
        for j in range(i, n - i - 1):
            # Store the top element of the current ring
            top_element = matrix[i][j]

            # Move elements from right to top
            for x in range(j, n - i - 1):
                rotated_matrix[i][x] = matrix[x + 1][j]

            # Move elements from bottom to right
            for y in range(i, n - i - 1):
                rotated_matrix[y][n - i - 1] = matrix[n - i - 1][y + 1]

            # Move elements from left to bottom
            for x in range(n - i - 1, i, -1):
                rotated_matrix[n - i - 1][x] = matrix[n - i - 2][x - 1]

            # Move the stored top element to the left
            rotated_matrix[n - i - 1][i] = top_element

    return rotated_matrix

