from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting and ending positions of the puck
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No start or end position found

    def is_valid_move(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def bfs(start_x, start_y):
        queue = [(start_x, start_y)]
        visited = set()
        moves = 0

        while queue:
            size = len(queue)
            for _ in range(size):
                x, y = queue.pop(0)

                if (x, y) == end_pos:
                    return moves

                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy

                    if is_valid_move(nx, ny) and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))

            moves += 1

    return bfs(start_pos[0], start_pos[1])
