def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    if not results:
        return []

    # Initialize the league table with zeros for each team
    table = {team: [0, 0, 0] for team in set(home + away for home, away, _, _ in results)}

    # Populate the league table based on the results
    for home, away, home_goals, away_goals in results:
        if home == away:
            table[home][0] += 1
            table[home][2] += abs(home_goals - away_goals)
            table[home][3] += home_goals
        else:
            table[home][0] += 3
            table[home][2] += abs(home_goals - away_goals)

    # Sort the table by points, goal difference, and goals scored, then by team name
    sorted_table = sorted(table.items(), key=lambda x: (-x[1][0], -x[1][2], -x[1][3], x[0]))

    # Convert the sorted table to the required format
    return [(team, *score) for team, score in sorted_table]

