def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]]:
    if start == goal:
        return (0, [start])

    # Create adjacency list representation of the graph
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    paths = {node: [] for node in graph}

    # Dijkstra's algorithm
    pq = [(0, start)]
    while pq:
        current_distance, current_node = heapq.heappop(pq)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = paths[current_node] + [current_node]
                heapq.heappush(pq, (distance, neighbor))

    # Find the shortest path
    shortest_path = min(paths.values(), key=lambda x: (sum(x), x))
    total_cost = sum(shortest_path)

    return (total_cost, shortest_path)
