from typing import List, Tuple

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]]:
    if start == goal:
        return (0, [start])

    # Build adjacency list
    adj_list = {node: [] for node in set(start + goal)}
    for u, v, w in edges:
        adj_list[u].append((v, w))
        adj_list[v].append((u, w))

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in adj_list}
    distances[start] = 0
    visited = set()
    path = []

    while len(visited) < len(adj_list):
        current_node = min(distances, key=distances.get)
        visited.add(current_node)

        for neighbor, weight in adj_list[current_node]:
            new_distance = distances[current_node] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                path.append(neighbor)

    if distances[goal] == float('inf'):
        return None

    # Reconstruct the path
    current_node = goal
    path.reverse()
    while current_node != start:
        path.insert(0, current_node)
        for neighbor, _ in adj_list[current_node]:
            if neighbor in path:
                current_node = neighbor
                break

    return (distances[goal], path)
