def parse_csv(text: str) -> list[list[str]]:
    records = []
    current_record = []
    in_quotes = False
    quote_char = None

    for char in text:
        if char == '"':
            if in_quotes:
                if quote_char == '"':
                    quote_char = None
                else:
                    quote_char = '"'
            else:
                in_quotes = True
                quote_char = '"'
        elif char == ',' and not in_quotes:
            if current_record:
                records.append(current_record)
                current_record = []
        elif char == '\n' and not in_quotes:
            if current_record:
                records.append(current_record)
                return records
            else:
                return []
        else:
