def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    max_lengths = [max(len(row[i]) for i in range(len(rows[0]))) for row in rows]
    formatted_rows = []

    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            align = aligns[i]
            padding = " " * (max_lengths[i] - len(cell))
            if align == "l":
                formatted_row.append(padding + cell)
            elif align == "r":
                formatted_row.append(cell + padding)
            else:
                formatted_row.append(cell.center(max_lengths[i]))
        formatted_rows.append(" ".join(formatted_row))

    return "\n".join(formatted_rows)
