    for char in text:
        if char == '"':
            if in_quote and quote_level > 0:
                # Closing quote found
                in_quote = False
                quote_level -= 1
            elif in_quote:
                # Opening quote found
                in_quote = True
                quote_level += 1
            else:
                # Start of a new quoted field
                in_quote = True
                quote_level = 1
        elif char == '\n' and not in_quote:
            # End of a record
            if current_record:
                records.append(current_record)
            current_record = []
        elif char != ',' and not in_quote:
            # Add character to the current record
            current_record.append(char)

    # Handle the last record if it's not closed by a newline
    if current_record:
        records.append(current_record)

    return records

