def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if len(matrix) == 0:
        return matrix

    n = len(matrix)

    # Create a new matrix to store the rotated rings
    rotated_matrix = [[0] * n for _ in range(n)]

    # Iterate over each ring
    for i in range(n // 2):
        # Calculate the start and end indices of the current ring
        start_row = i
