from collections import *

def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if tellers == 1:
        return [arrival - service_time for arrival, service_time in zip(arrivals, service_times)]

    waiting_times = []
    current_teller = 0
    current_service_time = 0

    for arrival in arrivals:
        while current_teller < tellers and current_service_time < service_times[current_teller]:
            waiting_times.append(current_service_time - arrival)
            current_service_time += 1

        if current_service_time >= service_times[current_teller]:
            current_teller += 1
            current_service_time = 0

    return waiting_times

