from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting point S and the exit point E
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def bfs(start: tuple) -> int:
        queue = [(start, 0)]
        visited = set()

        while queue:
            (x, y), steps = queue.pop(0)

            if (x, y) == end:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), steps + 1))

        return -1

    return bfs(start)
