def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return matrix

    rows = len(matrix)
    cols = len(matrix[0])

    def get_ring(ring_start, ring_end):
        ring = []
        for i in range(ring_start, ring_end + 1):
            for j in range(ring_start, ring_end + 1):
                ring.append(matrix[i][j])
        return ring

    def rotate_ring(ring, k):
        k %= len(ring)
        rotated_ring = ring[-k:] + ring[:-k]
        return rotated_ring

    def update_matrix(ring, start_row, start_col):
        for i in range(len(ring)):
            matrix[start_row + i][start_col + i] = ring[i]

    for r in range(rows // 2):
        for c in range(cols // 2):
            ring_start = r * cols + c
            ring_end = min((r + 1) * cols - 1, (c + 1) * rows - 1)

            ring = get_ring(ring_start, ring_end)
            rotated_ring = rotate_ring(ring, k)

            update_matrix(rotated_ring, r * cols + c, c * rows + r)

    return matrix
