import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    def is_number(s):
        if '.' in s:
            parts = s.split('.')
            return len(parts) == 2 and all(c.isdigit() for c in parts)
        return s.isdigit()

    def is_name(s):
        return s.isalnum() or s.startswith('_')

    def is_operator(s):
        return s in ['==', '!=', '<=', '>=', '+', '-', '*', '/', '<', '>', '=', '(', ')', ',', ';']

    tokens = []
    current_token = ''
    current_kind = None

    for char in source:
        if char.isspace():
            continue
        elif char == '\t':
            continue
        elif char == '\n':
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ''
            current_kind = None
            continue
        elif current_kind is None:
            if is_number(char):
                current_kind = 'NUMBER'
            elif is_name(char):
                current_kind = 'NAME'
            elif is_operator(char):
                current_kind = 'OP'
            else:
                raise ValueError(f"Invalid character: {char}")
        current_token += char

    if current_token:
        tokens.append((current_kind, current_token))

    return tokens
