def min_slides(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting and ending positions of S and E
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No start or end position found

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def dfs(x, y, moves):
        if (x, y) == end_pos:
            return moves

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_moves = dfs(nx, ny, moves + 1)
                if new_moves is not None:
                    return new_moves

    return dfs(start_pos[0], start_pos[1], 0)
