def matches_filter(expression: str, record: dict) -> bool:
    if not isinstance(record, dict):
        raise ValueError("Record must be a dictionary")

    def evaluate_expression(expr):
        try:
            return eval(expr)
        except Exception as e:
            raise ValueError(f"Invalid expression: {e}")

    def parse_expression(expr):
        tokens = expr.split()
        stack = []
        operators = {
            '<': operator.lt,
            '>': operator.gt,
            '==': operator.eq,
            '!=': operator.ne,
            '<=': operator.le,
            '>=': operator.ge,
            'and': lambda x, y: x and y,
            'or': lambda x, y: x or y,
            'not': lambda x: not x
        }

        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token.isalpha():
                if token in record:
                    stack.append(record[token])
