from typing import List

def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if len(arrivals) != len(service_times):
        raise ValueError("The lengths of arrivals and service times lists must be equal.")

    # Initialize the result list with zeros
    waiting_times = [0] * len(arrivals)

    # Sort the customers by their arrival times
    sorted_indices = sorted(range(len(arrivals)), key=lambda i: arrivals[i])

    current_time = 0

    for i in sorted_indices:
        # Find the next available teller
        while current_time < arrivals[i] and all(tellers[j] == 0 for j in range(tellers)):
            current_time += 1

        # If no teller is available, break the loop
        if current_time >= arrivals[i]:
            break

        # Update the waiting time for this customer
        waiting_times[i] = current_time - arrivals[i]

        # Mark the teller as busy
        for j in range(tellers):
            if arrivals[i] <= current_time + service_times[j]:
                tellers[j] = 1

    return waiting_times

