import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    def match_number(text):
        match = re.fullmatch(r'\d+(\.\d+)?', text)
        if match:
            return ('NUMBER', match.group())
        raise ValueError(f"Invalid number: {text}")

    def match_name(text):
        match = re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*', text)
        if match:
            return ('NAME', match.group())
        raise ValueError(f"Invalid name: {text}")

    def match_operator(text):
        for op in ['==', '!=', '<=', '>=', '+', '-', '*', '/', '<', '>', '=', '(', ')', ',']:
            if text == op:
                return ('OP', op)
        raise ValueError(f"Invalid operator: {text}")

    tokens = []
    current_text = ''
    for char in source:
        if char in ' \t\n':
            if current_text:
                tokens.append(match_number(current_text) if current_text.isdigit() else match_name(current_text) if current_text.isalpha() else match_operator(current_text))
                current_text = ''
        else:
            current_text += char
    if current_text:
        tokens.append(match_number(current_text) if current_text.isdigit() else match_name(current_text) if current_text.isalpha() else match_operator(current_text))

