def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    max_lengths = [max(len(cell) for cell in col) for col in zip(*rows)]
    formatted_rows = []
    for row in rows:
        formatted_row = ""
        for i, cell in enumerate(row):
            alignment = aligns[i]
            padding = " " * (max_lengths[i] - len(cell))
            if alignment == "l":
                formatted_row += cell + padding
            elif alignment == "r":
                formatted_row += padding + cell
            else:
                formatted_row += padding + cell + padding
        formatted_rows.append(formatted_row)

    return "\n".join(formatted_rows)
