from typing import List, Tuple

def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    team_points = {}
    for home, away, home_goals, away_goals in results:
        if home in team_points:
            team_points[home]['total'] += 3 if home_goals > away_goals else (2 if home_goals == away_goals else 0)
            team_points[home]['goals_scored'] += home_goals
            team_points[home]['goals_received'] += away_goals
        else:
            team_points[home] = {'total': 3 if home_goals > away_goals else (2 if home_goals == away_goals else 0),
                                'goals_scored': home_goals,
                                'goals_received': away_goals}

        if away in team_points:
            team_points[away]['total'] += 3 if away_goals > home_goals else (2 if away_goals == home_goals else 0)
            team_points[away]['goals_scored'] += away_goals
            team_points[away]['goals_received'] += home_goals
        else:
            team_points[away] = {'total': 3 if away_goals > home_goals else (2 if away_goals == home_goals else 0),
                                'goals_scored': away_goals,
                                'goals_received': home_goals}

    sorted_teams = sorted(team_points.items(), key=lambda x: (-x[1]['total'], -x[1]['goals_scored'], -x[1]['goals_received'], x[0]))

    return [(team, total, scored - received, scored) for team, info in sorted_teams]
