    op_pattern = r'(\+=|\-=|*=|/=|[<>]=?|==|!=|<|>|;)\s*'

    # Tokenize the source string using the defined patterns
    tokens = []
    current_token = ''
    current_kind = None

    for char in source:
        if char == ' ' or char == '\t':
            continue  # Skip spaces and tabs

