            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ''
                current_kind = None
            continue  # Skip newlines

        if current_kind is None:
            if re.match(number_pattern, char):
                current_kind = 'NUMBER'
            elif re.match(name_pattern, char):
