def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    max_widths = [max(len(cell) for cell in row) for row in rows]
    formatted_rows = []

    for i, row in enumerate(rows):
        formatted_row = ""
        for j, cell in enumerate(row):
            align = aligns[j]
            padding = " " * (max_widths[j] - len(cell))
            if align == "l":
                formatted_row += cell + padding
            elif align == "r":
                formatted_row += padding + cell
            else:
                formatted_row += padding.center(max_widths[j])
        formatted_rows.append(formatted_row)

    return "\n".join(formatted_rows) + "\n"
