    # Check if URL starts with https://
    if not url.startswith('https://'):
        return False

    # Remove leading/trailing whitespaces and convert to lowercase
    url = url.strip().lower()

    # Check for invalid characters
    if re.search(r'[^a-zA-Z0-9.-]', url):
        return False

    # Split URL into components
    parts = url.split('/')

    # Check for invalid components
    if len(parts) < 3 or parts[0] != 'www':
        return False

    # Check for invalid domain
    domain = parts[1]
    if '.' in domain:
        labels = domain.split('.')
        if len(labels) < 2 or any(not label.isalnum() or '-' in label for label in labels):
            return False
        if labels[-1].isdigit():
            return False
        if labels[-1] == 'localhost':
            return False
    else:
        return False

    # Check for invalid port
    if len(parts) > 2 and parts[2] != '443':
        return False

    return True
