from jinja2 import Template

def render_report_header(template: str, report: dict) -> str:
    # Replace placeholders with actual values from the report dictionary
    for key, value in report.items():
        template = template.replace(f'{{ {key} }}', str(value))

    # Handle conditional rendering using {% if %}
    if 'draft' in report:
        template = template.replace('{% if report.draft %}', '{% if True %}')
        template = template.replace('{% endif %}', '{% endif %}')

    return template
