def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if not arrivals or not service_times:
        return []

    # Initialize variables to keep track of the waiting times and available cajeros
    waiting_times = [0] * len(arrivals)
    available_cajeros = [True] * tellers

    # Sort the arrivals by time
    sorted_arrivals = sorted(zip(arrivals, service_times), key=lambda x: x[0])

    for arrival, service_time in sorted_arrivals:
        # Find the first available cajero
        for i in range(tellers):
            if available_cajeros[i]:
                waiting_times[i] = max(0, arrival - 0) + service_time
                available_cajeros[i] = False
                break

        # If all cajeros are busy, wait until one becomes free
        else:
            waiting_times.append(max(0, arrival - 0) + service_time)

