import re

def matches_filter(expression: str, record: dict) -> bool:
    # Verificar si la expresión contiene caracteres inválidos
    if not re.match(r'^[a-zA-Z0-9<>=!&|()]*$', expression):
        raise ValueError("Expresión inválida")

    # Expresión regular para validar la estructura de la expresión
    pattern = r'(?P<key>\w+)\s*(?P<operator>[<>!=&|])\s*(?P<value>(\d+(\.\d+)?|[\'"]([^\'"]*)[\'"])?)'

    for match in re.finditer(pattern, expression):
        key = match.group('key')
        operator = match.group('operator')
        value = match.group('value')

        if key not in record:
            return False

        if operator == '<':
            if float(record[key]) >= float(value):
                return False
        elif operator == '>':
            if float(record[key]) <= float(value):
                return False
        elif operator == '==':
            if record[key] != value:
                return False
        elif operator == '!=':
            if record[key] == value:
                return False
        elif operator == '&':
            if not (float(record[key]) >= float(value)):
                return False
        elif operator == '|':
            if not (float(record[key]) <= float(value)):
                return False
        elif operator == '!':
            if record[key]:
                return False

    return True
