from collections import deque

def evaluate_expression(expr: str) -> int:
    precedence = {'(': 0, '+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    operators = {'+', '-', '*', '/', '^'}
    stack = deque()
    tokens = expr.replace(' ', '').split()

    def apply_operator(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b
        elif op == '^':
            return a ** b

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token in operators:
            while stack and stack[-1] != '(' and precedence[token] <= precedence[stack[-1]]:
                b = stack.pop()
                a = stack.pop()
                stack.append(apply_operator(stack.pop(), b, a))
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack[-1] != '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(apply_operator(stack.pop(), b, a))
            stack.pop()  # Remove '(' from the stack

    while stack:
