def evaluate_expression(expr: str) -> int:
    def parse_expr(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    right = stack.pop()
                    left = stack.pop()
                    stack.append(op.add(left, right) if token == '+' else 
                               op.sub(left, right) if token == '-' else 
                               op.mul(left, right) if token == '*' else 
                               op.truediv(left, right) if token == '/' else 
                               op.pow(left, right))
