from functools import reduce

def evaluate_expression(expr):
    def apply_operator(op_func, *args):
        return op_func(*args)

    def parse_expr(expr):
        if expr == '(':
            return parse_expr(expr[1:-1])
        elif expr.isdigit():
            return int(expr)
        elif expr.startswith('-'):
            return -parse_expr(expr[1:])
        else:
            left = parse_expr(expr.split('(')[0])
            right = parse_expr(expr.split(')')[1])
            return op_func(left, right)

    operators = {
        '+': op.add,
        '-': op.sub,
        '*': op.mul,
        '/': lambda x, y: int(x / y),
        '^': pow,
        '(': None,
        ')': None,
        ' ': None,
        'unary': lambda x: -x
    }

    stack = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isalnum() or char == '-' and i > 0 and expr[i-1].isalnum():
            num_str = ''
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                num_str += expr[i]
                i += 1
            stack.append(float(num_str))
        elif char in operators:
            if char == '(':
                stack.append(char)
            elif char == ')':
                while stack[-1] != '(':
                    op_func = operators[stack.pop()]
                    right = stack.pop()
                    left = stack.pop()
                    stack.append(op_func(left, right))
