import re

def is_allowed_webhook(url: str) -> bool:
    if not url.startswith("https://"):
        return False

    # Remove 'http://' or 'https://' from the URL
    url = url.replace("http://", "").replace("https://", "")

    # Check for invalid characters
    if any(char in url for char in "!@#$%^&*()_+[]{}|\\:;"'<>,.?/`~"):
        return False

    # Split the URL into components
    parts = url.split(":")

    # Check for invalid components
    if len(parts) != 2:
        return False

    host, port = parts

    # Check for invalid host
    if "@" in host:
        user, password = host.split("@")
        if not all(c.isalnum() or c in "-." for c in user):
            return False
        if not all(c.isalnum() or c in "-." for c in password):
            return False
    else:
        if not all(c.isalnum() or c in "-." for c in host):
            return False

    # Check for invalid port
    try:
        int(port)
    except ValueError:
        return False

    # Check for localhost and .localhost
    if host == "localhost" or host == ".localhost":
        return True

    # Check for valid domain
    if "." not in host:
        return False

    # Check for valid DNS labels
    labels = host.split(".")
    for label in labels:
        if not all(c.isalnum() or c in "-." for c in label):
            return False

    return True
