import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.startswith("https://"):
        return False

    # Remove any leading/trailing whitespace
    url = url.strip()

    # Check for disallowed characters
    if re.search(r'[^\w\s]', url):
        return False

    # Split URL into components
    parts = url.split('://')
    if len(parts) != 2:
        return False

    protocol, domain = parts

    # Check for invalid protocols
    if protocol.lower() not in ['http', 'https']:
        return False

    # Check for invalid domains
    if not re.match(r'^[a-zA-Z0-9.-]+$', domain):
        return False

    # Check for invalid ports
    if ':' in domain:
        try:
            port = int(domain.split(':')[1])
            if port < 1 or port > 65535:
                return False
        except ValueError:
            return False

    # Check for localhost and .localhost
    if domain == 'localhost' or domain.endswith('.localhost'):
        return False

    return True
