from jinja2 import Template

def render_report_header(template: str, report: dict) -> str:
    # Replace placeholders with actual values from the report dictionary
    for key, value in report.items():
        template = template.replace(f'{{ {key} }}', str(value))

    # Handle conditional blocks
    while '{% if ' in template:
        start_index = template.find('{% if ')
        end_index = template.find('%}', start_index)

        condition_key = template[start_index + 7:end_index]
        condition_value = report.get(condition_key, False)

        if condition_value:
            template = template[:start_index] + template[end_index + 1:]
        else:
            template = template[:start_index] + template[end_index:]

    return template

