def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.startswith("https://"):
        return False

    # Remove user@ or user:password@
    if "@" in url:
        url = url.split("@")[0]

    # Check for backslashes, spaces, and control characters
    if "\\" in url or " " in url or "\x00" <= ord(url[-1]) < 32:
        return False

    # Split host and port
    parts = url.split(":")
    host = parts[0]
    port = parts[1] if len(parts) > 1 else None

    # Check if host is a valid DNS name
    if "." in host:
        labels = host.split(".")
        if len(labels) < 2 or any(label == "" or not re.match(r'^[A-Za-z0-9-]+$', label) for label in labels[:-1]) or labels[-1] == "":
