def evaluate_expression(expr: str) -> int:
    # Define precedence for operators
    precedence = {'^': 3, '*': 2, '/': 2, '+': 1, '-': 1}

    # Function to apply parentheses
    def apply_parentheses(expr):
        while '(' in expr:
            i = expr.index('(')
            j = expr.rindex(')')
            sub_expr = expr[i + 1:j]
            result = apply_parentheses(sub_expr)
            expr = expr[:i] + str(result) + expr[j + 1:]
        return expr

    # Apply parentheses to ensure correct order of operations
    expr = apply_parentheses(expr)

    # Split the expression into tokens
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\^|\(|\)', expr)

    # Evaluate the expression using a stack
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '^':
                    stack.append(a ** b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    stack.append(a // b)
                elif op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
