from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = OrderedDict()
    results = []
    keys = []

    for operation, key, value in operations:
        if operation == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            results.append(value)
            keys.append(key)
            if len(cache) > capacity:
                oldest_key = next(iter(cache))
                del cache[oldest_key]
                results.append(None)
                keys.append(oldest_key)
        elif operation == "get":
            if key in cache:
                results.append(cache[key])
                keys.append(key)
            else:
                results.append(None)
                keys.append(None)

    return (results, keys)
