def min_slides(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No valid start or end position found

    def dfs(x, y, steps):
        if x < 0 or x >= rows or y < 0 or y >= cols or grid[x][y] == '#':
            return float('inf')

        if (x, y) == end_pos:
            return steps

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        min_steps = float('inf')

        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy
            min_steps = min(min_steps, dfs(new_x, new_y, steps + 1))

        return min_steps

    return dfs(start_pos[0], start_pos[1], 0)
