from typing import List

def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find the starting and ending positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1  # No path found

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = [start]
    visited = set([start])
    steps = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.pop(0)

            if (x, y) == end:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        steps += 1

    return -1  # No path found
