def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = None, None
    end_row, end_col = None, None

    # Find the starting and ending positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_row, start_col = i, j
            elif grid[i][j] == 'E':
                end_row, end_col = i, j

    if start_row is None or end_row is None:
        return -1  # No path found

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(x, y, visited):
        if x < 0 or x >= rows or y < 0 or y >= cols or grid[x][y] == '#' or visited[x][y]:
            return False

        if x == end_row and y == end_col:
            return True

        visited[x][y] = True
        for dx, dy in directions:
            if dfs(x + dx, y + dy, visited):
                return True
        return False

    visited = [[False] * cols for _ in range(rows)]
    return dfs(start_row, start_col, visited)
