import re

def parse_csv(text: str) -> list[list[str]]:
    def decode_quoted_field(field):
        if field[0] == '"':
            decoded = ''
            i = 1
            while i < len(field):
                if field[i] == '"':
                    if i + 1 < len(field) and field[i + 1] == '"':
                        decoded += '"'
                        i += 2
                    else:
                        break
                else:
                    decoded += field[i]
                    i += 1
            return decoded.strip('"')
        return field

    lines = text.split('\n')
    records = []
    current_record = []

    for line in lines:
        if line:
            fields = re.findall(r'"([^"]+)"|([^,]+)', line)
            for field in fields:
                if isinstance(field, tuple):
                    current_record.append(decode_quoted_field(field[0]))
                else:
                    current_record.append(field)
            records.append(current_record)
            current_record = []

    return records
