def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define precedence and associativity of operators
    precedence = {
        '^': 3,
        '*': 2,
        '/': 2,
        '+': 1,
        '-': 1
    }
    associativity = {
        '^': 'right',
        '*': 'left',
        '/': 'left',
        '+': 'left',
        '-': 'left'
    }

    # Helper function to apply an operator to two operands
    def apply_operator(operators, values):
        while operators and operators[-1] != '(' and precedence[operators[-1]] >= precedence[op]:
            op = operators.pop()
            right = values.pop()
            left = values.pop()
            if op == '^':
                values.append(left ** right)
            elif op == '*':
                values.append(left * right)
            elif op == '/':
                values.append(int(left / right))  # Truncate for integer division
            elif op == '+':
                values.append(left + right)
            elif op == '-':
                values.append(left - right)
        operators.append(op)
        values.append(right)

    # Helper function to parse the expression into tokens
    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                num = ''
                while i < len(expr) and expr[i].isdigit():
                    num += expr[i]
                    i += 1
                tokens.append(int(num))
            elif expr[i] in "+-*/^()":
                tokens.append(expr[i])
                i += 1
            elif expr[i] == '(':
                tokens.append('(')
                i += 1
            elif expr[i] == ')':
                tokens.append(')')
                i += 1
        return tokens

    # Main parsing and evaluation function
    def parse_and_evaluate(tokens):
        operators = []
        values = []

        for token in tokens:
            if token.isdigit():
                values.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
            else:
                while operators and operators[-1] != '(' and (
                        associativity[token] == 'left' or
                        (associativity[token] == 'right' and precedence[token] > precedence[operators[-1]])
                ):
                    apply_operator(operators, values)
                operators.append(token)

        while operators:
            apply_operator(operators, values)

        return values[0]

    # Tokenize the input expression
    tokens = tokenize(expr)

    # Evaluate the expression
    result = parse_and_evaluate(tokens)

    return result
