import re

def evaluate_expression(expr: str) -> int:
    # Remove all spaces from the expression
    expr = expr.replace(" ", "")

    # Define a regular expression pattern for matching numbers, operators, and parentheses
    pattern = r"(\d+|\+|-|\*|\/|\^|\(|\))"

    # Split the expression into tokens using the defined pattern
    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators and operands
    stack = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            # Push the number onto the stack
            stack.append(int(token))
        elif token == '(':
            # Push the opening parenthesis onto the stack
            stack.append(token)
        elif token == ')':
            # Pop operators until the corresponding opening parenthesis is found
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            # Pop the opening parenthesis
            stack.pop()
        elif token in "+-*/^":
            # Pop two operands and apply the operator
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                stack.append(a // b)
            elif token == '^':
                stack.append(a ** b)

        i += 1

    # The final result should be the only element left on the stack
    return stack[0]
