import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define the regular expression for matching numbers and operators
    pattern = r"(\d+|\-?\d+\.\d+)|\+|-|\*|\/|\^"
    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators and operands
    stack = []
    operators = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}

    # Iterate over each token in the expression
    for token in tokens:
        if token.isdigit():
            # If the token is a number, push it onto the stack
            stack.append(int(token))
        elif token == '.':
            # If the token is a decimal point, raise ValueError
            raise ValueError("Invalid expression")
        elif token in '+-*/^':
            # While the stack is not empty and the current operator has higher precedence than the top operator on the stack,
            # pop the top operator from the stack and apply it to the two operands on the stack
            while stack and operators[token] <= operators[stack[-1]]:
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            # Push the current operator onto the stack
            stack.append(token)
        elif token == '(':
            # If the token is an opening parenthesis, push it onto the stack
            stack.append(token)
        elif token == ')':
            # While the stack is not empty and the top operator on the stack is not an opening parenthesis,
            # pop the top operator from the stack and apply it to the two operands on the stack
            while stack and stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            # Pop the closing parenthesis from the stack
            stack.pop()

    # If there is more than one operand left on the stack, raise ValueError
    if len(stack) > 1:
        raise ValueError("Invalid expression")

    # Return the result of the expression
    return stack[0]
