def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.startswith('PUSH'):
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == 'POP':
            if stack:
                stack.pop()
            else:
                raise ValueError("Stack is empty")
        elif instruction == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                raise ValueError("Stack is empty")
        elif instruction == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                raise ValueError("Not enough elements on the stack")
        elif instruction == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
            else:
                raise ValueError("Not enough elements on the stack")
        elif instruction == 'SUB':
            if len(stack) >= 2:
                stack.append(stack.pop() - stack.pop())
            else:
                raise ValueError("Not enough elements on the stack")
        elif instruction == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
            else:
                raise ValueError("Not enough elements on the stack")
        elif instruction == 'JMP':
            target_index = int(instruction.split()[1])
            if target_index < len(program):
                return program[target_index:]
            else:
                raise IndexError("Target index out of range")
        elif instruction == 'JZ':
            if stack and stack[-1] == 0:
                target_index = int(instruction.split()[1])
                if target_index < len(program):
                    return program[target_index:]
                else:
                    raise IndexError("Target index out of range")
            else:
                pass
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Invalid instruction: {instruction}")
    if stack:
        raise ValueError("Stack is not empty after execution")
    return stack
