import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with 'https://' and has no special characters except '.' or ':'
    if not url.startswith('https://') or re.search(r'[^\w\.\:\-]', url):
        return False

    # Split URL into components
    parts = url.split(':')

    # Check if there's a port specified
    if len(parts) > 1:
        port = parts[1]
        if not port.isdigit() or int(port) != 443:
            return False

    # Extract host from URL
    host = parts[0].split('@')[0]

    # Validate host format
    if '@' in host:
        username, password = host.split('@')
        if not all(c.isalnum() for c in username) or not all(c.isalnum() or c == '-' for c in password):
            return False
    elif ':' in host:
        username, domain = host.split(':')
        if not all(c.isalnum() for c in username) or not all(c.isalnum() or c == '-' for c in domain):
            return False
    else:
        if not all(c.isalnum() or c == '-' for c in host):
            return False

    # Check if host is valid
    try:
        socket.gethostbyname(host)
    except socket.gaierror:
        return False

    return True
