def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        if instruction.startswith("PUSH"):
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == "POP":
            if stack:
                stack.pop()
            else:
                return None
        elif instruction == "DUP":
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif instruction == "SWAP":
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif instruction.startswith("ADD"):
            if len(stack) >= 2:
                a, b = stack.pop(), stack.pop()
                stack.append(a + b)
            else:
                return None
        elif instruction.startswith("SUB"):
            if len(stack) >= 2:
                a, b = stack.pop(), stack.pop()
                stack.append(a - b)
            else:
                return None
        elif instruction.startswith("MUL"):
            if len(stack) >= 2:
                a, b = stack.pop(), stack.pop()
                stack.append(a * b)
            else:
                return None
        elif instruction.startswith("JMP"):
            target_index = int(instruction.split()[1])
            if target_index < len(program):
                return [target_index]
            else:
                return None
        elif instruction.startswith("JZ"):
