def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.startswith('PUSH'):
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == 'POP':
            if not stack:
                raise ValueError("Stack is empty")
            stack.pop()
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Stack is empty")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith('ADD'):
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction.startswith('JMP'):
            target = int(instruction.split()[1])
            if target >= len(program):
                raise IndexError("Invalid jump target")
            return program[target:]
        elif instruction.startswith('JZ'):
            value = int(instruction.split()[1])
            if stack and stack[-1] == value:
                return program[target:]
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    if stack and stack[0] != 0:
        raise ValueError("Non-zero value left on the stack after execution")
    return stack
