from typing import List, Tuple

def process_orders(events: List[Tuple[str, str, int]]) -> Tuple[dict[str, int], List[Tuple[str, int]]]:
    stock = {}
    waiting = []

    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            if item in stock:
                if stock[item] >= quantity:
                    stock[item] -= quantity
                    waiting.append((item, quantity))
                else:
                    waiting.append((item, stock[item]))
            else:
                waiting.append((item, quantity))

    return (stock, waiting)
