def is_public_ip(ip_str: str) -> bool:
    # Regular expression for validating an IPv4 address
    ipv4_pattern = re.compile(r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])$')

    # Regular expression for validating an IPv6 address
    ipv6_pattern = re.compile(r'^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$')

    if not ipv4_pattern.match(ip_str) and not ipv6_pattern.match(ip_str):
        return False

    # Check if the IP is in a private range
    if ip_str.startswith('10.') or ip_str.startswith('172.16.0.0') and int(ip_str.split('.')[1]) >= 16 or ip_str.startswith('192.168.0.0') and int(ip_str.split('.')[1]) >= 16 or ip_str == '127.0.0.1':
        return False

    # Check if the IP is in a loopback range
    elif ip_str.startswith('127.0.0.0') and int(ip_str.split('.')[2]) > 0:
        return False

    # Check if the IP is in a link-local range
    elif ip_str.startswith('169.254.0.0') and int(ip_str.split('.')[1]) >= 16:
        return False

    # Check if the IP is in a multicast range
    elif ip_str.startswith('224.0.0.0') and int(ip_str.split('.')[1]) >= 16:
        return False

    # Check if the IP is in a reserved range
    elif ip_str in ['0.0.0.0', '255.255.255.255']:
        return False

    # Check if the IP is in a shared space range
    elif ip_str.startswith('100.64.0.0') and int(ip_str.split('.')[1]) < 10:
        return False

    # Check if the IP is the broadcast address of IPv4
    elif ip_str == '255.255.255.255':
        return False

    # Check if the IP is mapped to IPv4
    elif ip_str.startswith('::ffff:') and ip_str.endswith('.'):
        ipv4_part = ip_str.replace('::ffff:', '')
        return is_valid_ipv4(ipv4_part)

    return True

