import re

def is_allowed_webhook(url: str) -> bool:
    # Comprueba si la URL comienza con https://
    if not url.startswith("https://"):
        return False

    # Elimina cualquier barra invertida, espacio ni carácter de control
    url = ''.join(c for c in url if c.isalnum() or c in "-._")

    # Verifica si el host es un nombre DNS válido
    host = url.split("//")[1].split(":")[0]
    if len(host) < 2:
        return False
    labels = host.split(".")
    if len(labels) < 2 or any(label == "" for label in labels):
        return False
    for label in labels:
        if not re.match(r'^[A-Za-z0-9-]+$', label):
            return False
    if host.endswith('.localhost'):
        return False
    if host == 'localhost':
        return False

    # Verifica si el puerto es 443
    if ":" in url and url.split(":")[1] != "443":
        return False

    return True
