def is_anagram(s1: str, s2: str) -> bool:
    # Remove spaces and convert to lowercase
    s1 = s1.replace(" ", "").lower()
    s2 = s2.replace(" ", "").lower()

    # Check if lengths are equal
    if len(s1) != len(s2):
        return False

    # Count occurrences of each character in both strings
    count_s1 = {}
    count_s2 = {}

    for char in s1:
        if char in count_s1:
            count_s1[char] += 1
        else:
            count_s1[char] = 1

    for char in s2:
        if char in count_s2:
            count_s2[char] += 1
        else:
            count_s2[char] = 1

    # Compare character counts
    return count_s1 == count_s2
