from typing import List

def run_stack_machine(program: List[str]) -> List[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        instruction = program[ip]

        if instruction == "PUSH":
            try:
                value = int(instruction.split()[1])
                stack.append(value)
            except ValueError:
                raise ValueError("Invalid PUSH instruction")
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements for SWAP")
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif instruction == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough elements for ADD")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough elements for SUB")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough elements for MUL")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == "JMP":
            try:
                target = int(instruction.split()[1])
                if target >= len(program):
                    raise IndexError("Jump out of bounds")
                ip = target
            except ValueError:
                raise ValueError("Invalid JMP instruction")
        elif instruction == "JZ":
            try:
                target = int(instruction.split()[1])
                if stack[-1] == 0:
                    ip = target
                else:
                    ip += 1
            except ValueError:
                raise ValueError("Invalid JZ instruction")
        elif instruction == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        if ip >= max_instructions:
            raise RuntimeError("Too many instructions")

        ip += 1

    return stack
