class StackMachine:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        if not self.stack:
            raise ValueError("Stack is empty")
        return self.stack.pop()

    def dup(self):
        if not self.stack:
            raise ValueError("Stack is empty")
        self.stack.append(self.stack[-1])

    def swap(self):
        if len(self.stack) < 2:
            raise ValueError("Not enough elements to swap")
        self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]

    def add(self):
        if len(self.stack) < 2:
            raise ValueError("Not enough elements to add")
        self.stack.append(self.stack.pop() + self.stack.pop())

    def sub(self):
        if len(self.stack) < 2:
            raise ValueError("Not enough elements to subtract")
        self.stack.append(self.stack.pop() - self.stack.pop())

    def mul(self):
        if len(self.stack) < 2:
            raise ValueError("Not enough elements to multiply")
        self.stack.append(self.stack.pop() * self.stack.pop())

    def jmp(self, target):
        self.program_pointer = target

    def jz(self, target):
        if self.stack.pop() == 0:
            self.program_pointer = target

    def halt(self):
        raise RuntimeError("Halt instruction reached")

    def run(self, program):
        self.program_pointer = 0
        while True:
            instruction = program[self.program_pointer]
            if instruction.startswith('PUSH'):
                value = int(instruction.split()[1])
                self.push(value)
            elif instruction == 'POP':
                self.pop()
            elif instruction == 'DUP':
                self.dup()
            elif instruction == 'SWAP':
                self.swap()
            elif instruction == 'ADD':
                self.add()
            elif instruction == 'SUB':
                self.sub()
            elif instruction == 'MUL':
                self.mul()
            elif instruction == 'JMP':
                target = int(instruction.split()[1])
                self.jmp(target)
            elif instruction == 'JZ':
                target = int(instruction.split()[1])
                self.jz(target)
            elif instruction == 'HALT':
                self.halt()
            else:
                raise ValueError(f"Unknown instruction: {instruction}")
            self.program_pointer += 1

