def run_stack_program(program: List[str]) -> List[int] | None:
    stack = []
    ip = 0

    while ip < len(program):
        instruction = program[ip]

        if instruction.startswith('PUSH'):
            _, num = instruction.split()
            stack.append(int(num))
        elif instruction == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif instruction == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif instruction == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif instruction in ['ADD', 'SUB', 'MUL']:
            if len(stack) >= 2:
                b, a = stack.pop(), stack.pop()
                if instruction == 'ADD':
                    stack.append(a + b)
                elif instruction == 'SUB':
                    stack.append(a - b)
                elif instruction == 'MUL':
                    stack.append(a * b)
            else:
                return None
        elif instruction.startswith('JMP'):
            _, target = instruction.split()
            ip = int(target)
        elif instruction.startswith('JZ'):
            _, target = instruction.split()
            if stack and stack[-1] == 0:
                ip = int(target)
            else:
                ip += 1
        else:
            return None

        ip += 1

    return stack
