def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pointer = 0

    while pointer < len(program):
        instruction = program[pointer]

        if instruction == "PUSH":
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack for addition")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack for subtraction")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack for multiplication")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == "JMP":
            pointer = int(instruction.split()[1])
        elif instruction == "JZ":
            if stack and stack[-1] == 0:
                pointer = int(instruction.split()[1])
            else:
                pointer += 1
        elif instruction == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        if pointer >= len(program):
            break

        pointer += 1

    return stack
