    stack = []
    instructions = {
        'PUSH': lambda n: stack.append(n),
        'POP': lambda: stack.pop() if stack else None,
        'DUP': lambda: stack.append(stack[-1]) if stack else None,
        'SWAP': lambda: stack.reverse() if stack else None,
        'ADD': lambda: stack.append(stack.pop() + stack.pop()) if stack else None,
        'SUB': lambda: stack.append(stack.pop() - stack.pop()) if stack else None,
        'MUL': lambda: stack.append(stack.pop() * stack.pop()) if stack else None,
        'JMP': lambda t: t,
        'JZ': lambda t: t if stack and stack.pop() == 0 else None
    }
    for i in range(len(program)):
        instruction = program[i].split()
        if len(instruction) != 2:
            return None
        op, arg = instruction[0], int(instruction[1])
        if op not in instructions:
            return None
        if op == 'JMP' or op == 'JZ':
            continue
        if op == 'PUSH':
            try:
                instructions[op](arg)
            except IndexError:
                return None
        elif op == 'POP':
            instructions[op]()
        elif op == 'DUP':
            instructions[op]()
        elif op == 'SWAP':
            instructions[op]()
