            stack.append(a + b)
        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instruction.startswith('JMP'):
            target = int(instruction.split()[1])
            if target >= len(program):
                return None
            instruction_pointer = target
        elif instruction.startswith('JZ'):
            target = int(instruction.split()[1])
            if stack and stack[-1] == 0:
                instruction_pointer = target
            else:
                instruction_pointer += 1
        else:
            return None

        if instruction_pointer >= len(program) or instruction_pointer > 1000:
            return None

        instruction_pointer += 1

    return stack

