def prefix_suffix_common(s: str) -> int:
    if len(s) == 0:
        return 0

    # Find the longest common prefix between the first half and the second half
    mid = len(s) // 2
    left_prefix = s[:mid]
    right_suffix = s[mid:]

    # Check if the left prefix is equal to the reversed right suffix
    if left_prefix == right_suffix[::-1]:
        return mid

    # If not, recursively find the common prefix in the first half and the second half
    return max(prefix_suffix_common(left_prefix), prefix_suffix_common(right_suffix))

