def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, 0
    direction = 1

    while True:
        result.append(matrix[i][j])

        # Move in the current direction
        if direction == 1:
            if j + 1 < cols:
                j += 1
            else:
                i += 1
                direction = -1
        elif direction == -1:
            if j - 1 >= 0:
                j -= 1
            else:
                i += 1
                direction = 1

        # Check if we've reached the end of the matrix
        if i >= rows or j >= cols:
            break

    return result
