def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, 0

    while True:
        # Add current row from left to right
        for _ in range(cols):
            if i < rows:
                result.append(matrix[i][j])
                i += 1

        # If we've reached the end of the last row, break
        if i == rows:
            break

        # Add current row from right to left
        for _ in range(cols - 1, -1, -1):
            if j < cols:
                result.append(matrix[i][j])
                j += 1

        # If we've reached the start of the first row, break
        if j == cols:
            break

    return result
