import re

def evaluate_expression(expression: str) -> float:
    # Remove any leading/trailing whitespace
    expression = expression.strip()

    # Check if the expression is empty
    if not expression:
        raise ValueError("Expression cannot be empty")

    # Define the regular expression pattern for matching the expression
    pattern = r"[-+]?\d+(\.\d+)?([*/+-]**)?([-+]?\d+(\.\d+)?)?"

    # Match the expression against the pattern
    match = re.match(pattern, expression)

    if not match:
        raise ValueError("Invalid expression format")

    # Extract the operands and operator from the matched groups
    operands = [match.group(i) for i in range(1, 6)]
    operator = match.group(7)

    # Convert operands to floats
    try:
        operands = [float(op) for op in operands]
    except ValueError as e:
        raise ValueError(f"Invalid operand: {e}")

    # Evaluate the expression based on the operator
    if operator == '+':
        result = sum(operands)
    elif operator == '-':
        result = operands[0] - sum(operands[1:])
    elif operator == '*':
        result = operands[0] * operands[1]
    elif operator == '/':
        if operands[1] == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        result = operands[0] / operands[1]
    elif operator == '**':
        result = operands[0] ** operands[1]
    else:
        raise ValueError("Unknown operator")

    return result
