def shortest_path_one_break(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = [(start_pos[0], start_pos[1], 0)]
    visited = set()

    while queue:
        x, y, steps = queue.pop(0)

        if (x, y) == end_pos:
            return steps

