from math import gcd

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders
    moduli = [r[1] for r in congruences]
    remainders = [r[0] for r in congruences]

    # Compute the product of all moduli
    M = lcm(*moduli)

    # Compute the partial products
    partial_products = [M // m for m in moduli]

    # Compute the inverse of each partial product modulo its corresponding modulus
    inverses = [pow(partial_product, -1, m) for partial_product, m in zip(partial_products, moduli)]

    # Compute the solution using the Chinese Remainder Theorem
    x = sum(r * p * inv for r, p, inv in zip(remainders, partial_products, inverses)) % M

    return (x, M)
