    # Sort the teams based on the criteria
    sorted_teams = sorted(league.items(), key=lambda x: (-x[1]['score'], -x[1]['goals_scored'], -x[1]['goals_conceded'], x[0]))

    # Format the output
    return [(team, score, goals_scored - goals_conceded, goals_scored) for team, score in sorted_teams]
