from typing import List, Tuple

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]]:
    # Initialize distances and predecessors
    distances = {node: float('inf') for node in set(u for u, _, _ in edges)}
    distances[start] = 0
    predecessors = {node: None for node in distances}

    # Priority queue to store nodes to visit
    import heapq
    heap = [(0, start)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # If we've found the goal, reconstruct the path
        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = predecessors[current_node]
            return (current_distance, path[::-1])

        # Explore neighbors
        for neighbor, weight in edges:
            distance_through_current = current_distance + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                predecessors[neighbor] = current_node
                heapq.heappush(heap, (distance_through_current, neighbor))

    # If no path was found
    return None
