import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    current_token = ""
    current_kind = None

    def add_token(kind):
        nonlocal current_token, current_kind
        if current_token:
            tokens.append((current_kind, current_token))
            current_token = ""
        current_kind = kind

    for char in source:
        if char == " " or char == "\t" or char == "\n":
            if current_token:
                add_token(current_kind)
            current_token = ""
            current_kind = None
        elif char.isdigit():
            if current_kind != "NUMBER":
                add_token("NUMBER")
            current_token += char
        elif char.isalpha() or char == "_":
            if current_kind != "NAME":
                add_token("NAME")
            current_token += char
        elif char in "+-*/<=>(),:;":
            if current_kind != "OP":
                add_token("OP")
            current_token += char
        else:
            raise ValueError(f"Invalid character '{char}'")

    if current_token:
        add_token(current_kind)

    return tokens
