        while i < len(field):
            if field[i] == '"':
                if i + 1 < len(field) and field[i + 1] == '"':
                    result.append('"')
                    i += 2
                else:
                    j = i + 1
                    while j < len(field) and field[j] != '"':
                        j += 1
                    result.append(field[i:j])
                    i = j
            else:
                result.append(field[i])
                i += 1
        return result

    lines = text.split('\n')
    records = []
    current_record = []

    for line in lines:
        if line.strip() == '':
            if current_record:
                records.append(current_record)
                current_record = []
        elif line.endswith(','):
            current_record.append(parse_field(line[:-1]))
