def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting position 'S'
    start_pos = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
                break

    if start_pos is None:
        return -1  # No starting position found

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

