        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def bfs(start: tuple) -> int:
        queue = [(start, 0)]
        visited = set()

        while queue:
            pos, steps = queue.pop(0)

            if pos == end:
                return steps

            for dx, dy in directions:
                nx, ny = pos[0] + dx, pos[1] + dy

                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), steps + 1))

        return -1

    end_pos = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'E':
                end_pos = (i, j)
                break

    if end_pos is None:
        return -1  # No ending position found

    return bfs(start_pos)
