def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    max_lengths = [max(len(cell) for cell in col) for col in zip(*rows)]
    formatted_rows = []

    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            if aligns[i] == 'l':
                formatted_cell = cell.ljust(max_lengths[i])
            elif aligns[i] == 'r':
                formatted_cell = cell.rjust(max_lengths[i])
            else:
                formatted_cell = cell.center(max_lengths[i])
            formatted_row.append(formatted_cell)

        formatted_rows.append(' | '.join(formatted_row))

    return '\n'.join(formatted_rows)
