def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            # Calculate the new position after rotation
            new_i = (i + k) % n
            new_j = (j + k) % n

            # If the new position is out of bounds, wrap around
            if new_i == -1:
                new_i = n - 1
            elif new_i == n:
                new_i = 0
            if new_j == -1:
                new_j = n - 1
            elif new_j == n:
                new_j = 0

            result[new_i][new_j] = matrix[i][j]

    return result
