def rotate_rings(matrix: List[List[int]], k: int) -> List[List[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n // 2):
        start_row, end_row = i, n - i - 1
        start_col, end_col = i, n - i - 1

        for row in range(start_row, end_row + 1):
            for col in range(start_col, end_col + 1):
                result[end_col - col][start_row + row] = matrix[row][col]

    return result
