    pattern = r"(\d+|\+|-|\*|\/|\^|\(|\))"

    # Split the expression into tokens
    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators
    stack = []

    # Iterate through each token
    for token in tokens:
        if token.isdigit():
            # Push digits onto the stack
            stack.append(int(token))
        elif token == '(':
            # Push opening parenthesis onto the stack
            stack.append(token)
        elif token == ')':
            # Pop operators from the stack until an opening parenthesis is encountered
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    stack.append(a // b)
                elif op == '^':
