                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            stack.append(token)

    # Evaluate the remaining operators in the stack
    while len(stack) > 1:
