import re

def evaluate_expression(expr: str) -> int:
    # Remove all whitespace
    expr = expr.replace(" ", "")

    # Define the regular expressions for each operator
    patterns = {
        '+': r'\+',
        '-': r'-',
        '*': r'\*',
        '/': r'\/',
        '^': r'^'
    }

    # Replace each operator with its corresponding regex pattern
    for op, pattern in patterns.items():
        expr = re.sub(pattern, f'\\{op}', expr)

    # Evaluate the expression using eval()
    try:
        return eval(expr)
    except ZeroDivisionError:
        raise ValueError("Division by zero")
