    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators and operands
    stack = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            # Push numeric literals onto the stack
            stack.append(int(token))
        elif token == '(':
            # Push opening parenthesis onto the stack
            stack.append(token)
        elif token == ')':
