from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = OrderedDict()
    results = []
    keys = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            keys.append(key)
            if len(cache) > capacity:
                oldest_key = next(iter(cache))
                del cache[oldest_key]
                keys.remove(oldest_key)
        elif op == "get":
            if key in cache:
                keys.remove(key)
                keys.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    return (results, keys)
