def is_circular_shift(s1: str, s2: str) -> bool:
    # Check if both strings are empty or have the same length
    if len(s1) == 0 and len(s2) == 0:
        return True
    elif len(s1) != len(s2):
        return False

    # Concatenate the first string with itself
    doubled_s1 = s1 + s1

    # Check if the second string is a substring of the doubled string
    return s2 in doubled_s1

