def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    # Implementación del algoritmo de Dijkstra para encontrar la ruta más barata
    distances = {node: float('inf') for node in set(edge[0] for edge in edges) | set(edge[1] for edge in edges)}
    distances[start] = 0
    visited = set()

    while len(visited) < len(distances):
        current_node = min((node, distance) for node, distance in distances.items() if node not in visited)[0]
        visited.add(current_node)

        for neighbor, weight in edges:
            if neighbor == current_node and distance + weight < distances[neighbor]:
                distances[neighbor] = distance + weight

    if distances[goal] == float('inf'):
        return None

    path = []
    current_node = goal
    while current_node != start:
        path.append(current_node)
        for neighbor, weight in edges:
            if neighbor == current_node:
                current_node = start
                break

    path.append(start)
    path.reverse()

    return distances[goal], path
