def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    rows = len(matrix)
    cols = len(matrix[0])
    result = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            new_i = (i + k) % rows
            new_j = (j + k) % cols
            result[new_i][new_j] = matrix[i][j]

    return result

