from typing import List

def longest_bitonic_length(nums: List[int]) -> int:
    n = len(nums)

    # Initialize increasing and decreasing arrays
    inc = [1] * n
    dec = [1] * n

    # Fill increasing array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill decreasing array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum length of bitonic subsequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, inc[i] + dec[i] - 1)

    return max_length
```

