def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    result = ''
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            result = '-' + result
            n -= 6
        elif remainder == 1:
            result = '+' + result
            n -= 3
        else:
            result = '0' + result
            n -= 1

        n //= 3

    return result
```

