from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize distances and predecessors
    dist = [float('inf')] * n
    pred = [-1] * n

    # Distance from source to itself is 0
    dist[source] = 0

    # Priority queue to store nodes to visit
    pq = [(0, source)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node == target:
            break

        for neighbor in graph[current_node]:
            new_dist = current_dist + 1

            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                pred[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Count the number of shortest paths
    if dist[target] == float('inf'):
        return 0

    # Backtrack to find all shortest paths
    def backtrack(node):
        if node == source:
            return [[]]
        paths = []
        for prev in pred[node]:
            for path in backtrack(prev):
                paths.append([node] + path)
        return paths

    return len(backtrack(target))
