from typing import List, Tuple

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Initialize variables for the extended Euclidean algorithm
    x, y = 1, 0
    s, t = 0, 1

    for r, m in reversed(congruences):
        q = r // m
        x, y = y - q * x, x
        s, t = t - q * s, s

    # Adjust the solution to be positive and reduce modulo m
    x = (x + m) % m
    return (x, s)
