def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Invalid input")

    def to_decimal(num_str: str, base: int) -> int:
        return sum(int(digit) * (base ** power) for digit, power in zip(reversed(num_str), range(len(num_str))))

    def from_decimal(decimal_num: int, target_base: int) -> str:
        if decimal_num == 0:
            return "0"
        digits = []
        while decimal_num > 0:
            digits.append(chr(ord('0') + decimal_num % target_base))
            decimal_num //= target_base
        return ''.join(digits[::-1])

    if number[0] == '-':
        number = number[1:]
        decimal_number = -to_decimal(number, from_base)
    else:
        decimal_number = to_decimal(number, from_base)

    return '-' + from_decimal(decimal_number, to_base) if number[0] == '-' else from_decimal(decimal_number, to_base)
