def decode_runs(encoded: str) -> str:
    if not encoded:
        return ""

    decoded = []
    i = 0

    while i < len(encoded):
        char = encoded[i]

        if char.isdigit():
            count = int(char)
            i += 1

            # Append the character 'count' times to the decoded list
            decoded.extend([char] * count)
        else:
            decoded.append(char)
            i += 1

    return ''.join(decoded)
