import re

def is_allowed_webhook(url: str) -> bool:
    # Regular expression pattern for validating the URL
    pattern = r'^https://[a-zA-Z0-9.-]+(\.[a-zA-Z0-9.-]+)?(:[80|443])?$'

    # Check if the URL matches the pattern
    if re.match(pattern, url):
        # Split the URL into components
        parts = url.split('.')

        # Check if there are more than two labels
        if len(parts) > 2:
            return False

        # Check if the host part contains only alphanumeric characters, hyphens, and underscores
        if not all(char.isalnum() or char in '-_' for char in parts[0]):
            return False

        # Check if the port number is either 80 or 443
        if parts[-1] != '80' and parts[-1] != '443':
            return False

        # Check if the URL does not contain any DNS names
        if '.' in parts[1]:
            return False

        return True
    else:
        return False

