from typing import List, Tuple

def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    if not results:
        return []

    # Initialize a dictionary to store the league table data
    league_table = {}

    for home_team, away_team, home_goals, away_goals in results:
        # Calculate the points based on the goals scored
        points = home_goals + away_goals

        # Update the league table with the current match's data
        if home_team in league_table:
            league_table[home_team] += (points, home_goals - away_goals)
        else:
            league_table[home_team] = (points, home_goals - away_goals)

        if away_team in league_table:
            league_table[away_team] += (points, away_goals - home_goals)
        else:
            league_table[away_team] = (points, away_goals - home_goals)

    # Sort the league table based on the specified criteria
    sorted_table = sorted(league_table.items(), key=lambda x: (-x[1][0], -x[1][1], x[0]))

    # Extract the top 5 teams from the sorted table
    top_5_teams = sorted_table[:5]

    # Format the output as required
    formatted_output = [(team, *score) for team, score in top_5_teams]

