def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    # Normalize k to be within the range [0, n-1]
    k %= n

    # Perform the rotation
    for i in range(n):
        for j in range(i + k, n):
            # Swap matrix[i][j] with matrix[j][n-i-1]
            matrix[i][j], matrix[j][n-i-1] = matrix[j][n-i-1], matrix[i][j]

    return matrix

