from typing import List

def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start_x, start_y):
        queue = [(start_x, start_y, 0)]
        visited = set()

        while queue:
            x, y, moves = queue.pop(0)

            if (x, y) == (rows-1, cols-1):
                return moves

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny) and grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, moves + 1))

        return -1

    # Find the starting and ending positions
    start_x, start_y = None, None
    end_x, end_y = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
            elif grid[i][j] == 'E':
                end_x, end_y = i, j

    if start_x is None or end_x is None:
        return -1

    return bfs(start_x, start_y)
