from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find the starting and ending points
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1  # No starting or ending point found

    queue = deque([(start[0], start[1], 0)])
    visited = set()

    while queue:
        x, y, slides = queue.popleft()

        if (x, y) == end:
            return slides

        if (x, y) in visited:
            continue

        visited.add((x, y))

        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                queue.append((nx, ny, slides + 1))

    return -1  # Path cannot reach the end point
