from itertools import permutations

def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_valid(board, row, col):
        for i in range(row):
            if board[i][col] == 1:
                return False

        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        for i, j in zip(range(row, -1, -1), range(col, n)):
            if board[i][j] == 1:
                return False

        return True

    def backtrack(board, row):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if (row, col) not in blocked and is_valid(board, row, col):
                board[row][col] = 1
                count += backtrack(board, row + 1)
