def tidy_punctuation(text: str) -> str:
    """
    This function takes a string 'text' and performs several cleaning steps to make it more readable.

    Steps:
    1. Replace all whitespace characters (spaces, tabs, newlines) with a single space.
    2. Add spaces before and after punctuation marks such as ',', '.', ';', ':', '!', '?'.
    3. If a character is followed by another character that is a letter, add a space before the letter.
    4. Convert the first character and any punctuation at the beginning or end of the string to uppercase.
    5. Leave other characters unchanged.
    """
    # Step 1: Replace all whitespace characters with a single space
    text = " ".join(text.split())

    # Step 2: Add spaces before and after punctuation marks
    for char in ",.;:-!?":
        text = text.replace(char + char, char + " " + char)

    # Step 3: Add spaces before letters if they follow punctuation
    for i in range(len(text)):
        if text[i] in ",.;:-!?":
            if i < len(text) - 1 and text[i+1].isalpha():
                text = text[:i+1] + " " + text[i+1:]

    # Step 4: Convert the first character and any punctuation at the beginning or end to uppercase
    if text.startswith(","):
        text = text[1:].upper()
    elif text.endswith(","):
        text = text[:-1].upper() + ","
    elif text.startswith(";"):
        text = text[1:].upper()
    elif text.endswith(";"):
        text = text[:-1].upper() + ";"
    elif text.startswith(":"):
        text = text[1:].upper()
    elif text.endswith(":"):
        text = text[:-1].upper() + ":"
    elif text.startswith("!"):
        text = text[1:].upper()
    elif text.endswith("!"):
        text = text[:-1].upper() + "!"
    elif text.startswith("?"):
        text = text[1:].upper()
    elif text.endswith("?"):
        text = text[:-1].upper() + "?"

    return text
