from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No valid starting or ending position found

    # Directions for movement
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = [(start_pos, 0)]  # Queue to store positions and their moves
    visited = set()

    while queue:
        pos, moves = queue.pop(0)

        if pos == end_pos:
            return moves

        for dx, dy in directions:
            new_x, new_y = pos[0] + dx, pos[1] + dy

            if 0 <= new_x < rows and 0 <= new_y < cols and grid[new_x][new_y] != '#' and (new_x, new_y) not in visited:
                visited.add((new_x, new_y))
                queue.append(((new_x, new_y), moves + 1))

    return -1  # Exit cell cannot be reached
