def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1

    # Directions for movement
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    queue = [start_pos]
    visited = set()
    steps = 0

    while queue:
        level_size = len(queue)

        for _ in range(level_size):
            x, y = queue.pop(0)

            if (x, y) == end_pos:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        steps += 1

    return -1
