def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        return '-' if from_base == 10 else ''

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    num = 0

    for char in number:
        if char.isdigit():
            num = num * from_base + int(char)
        elif char.isalpha():
            num = num * from_base + digits.index(char.lower())
        else:
            raise ValueError("Invalid character in the number")

    if num == 0:
        return '-'

    result = ""
    while num > 0:
        result = digits[num % to_base] + result
        num //= to_base

    return result.lstrip('0')
