import re

def evaluate_expression(expr: str) -> int:
    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("division by zero")
            return a // b
        elif op == '^':
            return a ** b
        else:
            raise ValueError(f"Unsupported operator: {op}")

    def parse_expression():
        tokens = re.findall(r'\d+|\+|-|\*|/|^|\(|\)', expr)
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in "+-*/^":
                while stack and stack[-1] != '(' and (token in "+-*" or (token == "^" and stack[-1] != "(")):
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(apply_operator(stack.pop(), a, b))
                stack.append(token)
            elif token == '(':
