            elif token == ')':
                while stack[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(apply_operator(stack.pop(), a, b))
                stack.pop()  # Remove the '('

        while stack:
            b = stack.pop()
            a = stack.pop()
            stack.append(apply_operator(stack.pop(), a, b))

        return stack[0]

