import re

def evaluate_expression(expr: str) -> int:
    # Regular expression for matching numbers, operators, and parentheses
    pattern = r'[-+]?\d+(\.\d+)?|[\+\-\*/\^\(\)]'

    # Split the expression into tokens based on the pattern
    tokens = re.findall(pattern, expr)

    # Define a stack to keep track of operands and operators
    stack = []

    # Define a mapping of operators to their precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}

    # Iterate through each token in the expression
    for token in tokens:
        if token.isdigit():
            # If it's a number, push it onto the stack
            stack.append(int(token))
        elif token == '(':
            # If it's an opening parenthesis, push it onto the stack
            stack.append(token)
        elif token == ')':
            # If it's a closing parenthesis, pop from the stack until an opening parenthesis is found
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            stack.pop()  # Pop the opening parenthesis

    # If there's only one element left in the stack, it's the result
    return stack[0]
