import math

def evaluate_formula(formula: str, x: float) -> float:
    try:
        # Replace 'x' with the actual value of x in the formula
        formula = formula.replace('x', str(x))

        # Evaluate the formula using Python's built-in eval function
        result = eval(formula)

        return result
    except ZeroDivisionError:
        raise ValueError("Cannot divide by zero")
    except ValueError as e:
        raise ValueError(e)

# Example usage:
