print(evaluate_formula("sqrt(x) + 1", 16))  # Output: 5.0
try:
    print(evaluate_formula("x**2 / 0", 2))  # Raises ZeroDivisionError
except ValueError as e:
    print(e)  # Output: Cannot divide by zero
try:
    print(evaluate_formula("invalid_formula", 2))  # Raises ValueError
except ValueError as e:
    print(e)  # Output: invalid_formula is not a valid formula
