class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.keys_order = []

    def put(self, key, value):
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) == self.capacity:
            self.cache.pop(self.keys_order[0])
            self.keys_order.pop(0)
        self.cache[key] = value
        self.keys_order.append(key)

    def get(self, key):
        if key in self.cache:
            self.keys_order.remove(key)
            self.keys_order.append(key)
            return self.cache[key]
        else:
            return None

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    lru_cache = LRUCache(capacity)
    results = []
    keys = []

    for op, *args in operations:
        if op == "put":
            lru_cache.put(*args)
        elif op == "get":
            result = lru_cache.get(*args)
            results.append(result)
            keys.append(args[0])

    return results, keys
