import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if source.strip() == "":
        return []

    def match_number(text):
        return re.fullmatch(r'\d+(\.\d+)?', text)

    def match_name(text):
        return re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*', text)

    def match_operator(text):
        return re.fullmatch(r'([<>]=?|==|!=|[+\-*\/<>\(\),])', text)

    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue

        if source[i] == '.':
            if i + 1 >= len(source) or not match_number(source[i+1:]):
                raise ValueError("Invalid number after dot")
            tokens.append(("NUMBER", source[i:i+1]))
            i += 1
            continue

        if match_number(source[i:]):
            match = match_number(source[i:])
