from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting_orders = defaultdict(list)

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
        elif kind == 'order':
            if item in waiting_orders:
                waiting_orders[item].append((quantity, stock[item]))
            else:
                waiting_orders[item].append((quantity, 0))

    final_stock = {}
    waiting_orders_list = []

    for item, orders in waiting_orders.items():
        if orders:
            # Process orders in order of decreasing quantity
            while orders:
                quantity, current_stock = orders.pop()
                if current_stock >= quantity:
                    final_stock[item] += quantity
                    current_stock -= quantity
                else:
                    waiting_orders[item].insert(0, (quantity - current_stock, current_stock))
            if waiting_orders[item]:
                waiting_orders_list.append((item, waiting_orders[item]))

    return final_stock, waiting_orders_list
