    # Sort teams based on points, goal difference, and goals scored
    sorted_teams = sorted(team_points.items(), key=lambda x: (-x[1], -x[0][1], -x[0][2]))

    # Format the result as required
    formatted_result = [(team, points, abs(goals_diff), goals_scored) for team, points, goals_diff, goals_scored in sorted_teams]

    return formatted_result
