def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = {}
    keys_order = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            keys_order.append(key)
            if len(keys_order) > capacity:
                keys_order.pop(0)
        elif op == "get":
            if key in cache:
                keys_order.remove(key)
                keys_order.append(key)
                return [cache[key], keys_order]
            else:
                return [None, keys_order]

    return [None] * len(operations), keys_order
