def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif parts[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif parts[0] == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack[-1] + stack[-2])
            else:
                return None
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(stack[-2] - stack[-1])
            else:
                return None
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack[-1] * stack[-2])
            else:
                return None
        elif parts[0] == 'JMP':
            try:
                jump_to = int(parts[1])
                if jump_to < 0 or jump_to >= len(program):
                    return None
                continue
            except ValueError:
                return None
        elif parts[0] == 'JZ':
            try:
                jump_to = int(parts[1])
                if stack and stack[-1] == 0:
                    continue
            except ValueError:
                return None
    return stack
