def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    """
    Simulates a sandpile by repeatedly toppling grains until no more grains can be toppled.

    Parameters:
    - grid: A 2D list of integers representing the initial state of the sandpile.

    Returns:
    - A 2D list of integers representing the final state of the sandpile after stabilization.
    """
    # Helper function to check if a cell has enough grains to topple
    def can_topple(row, col):
        return grid[row][col] >= 4

    # Helper function to perform a single toppling operation
    def topple(row, col):
        if can_topple(row, col):
            grid[row][col] -= 4
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = row + dr, col + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    grid[nr][nc] += 1

    # Main loop to stabilize the sandpile
    while True:
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if can_topple(r, c):
                    topple(r, c)
                    changed = True
        if not changed:
            break

    return grid
