import re

def parse_csv(text: str) -> list[list[str]]:
    def split_field(field):
        if field.startswith('"'):
            return [field[1:-1]]  # Remove surrounding quotes
        else:
            return [field]

    lines = text.split('\n')
    records = []
    current_record = []

    for line in lines:
        if line.strip() == '':
            if current_record:
                records.append(current_record)
                current_record = []
        elif line.endswith(','):
            current_record.append(split_field(line[:-1]))
        else:
            current_record.extend(split_field(line))

    if current_record:
        records.append(current_record)

    return records
