def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    table = {}

    for home, away, home_goals, away_goals in results:
        if home not in table:
            table[home] = {'wins': 0, 'losses': 0, 'draws': 0, 'total_points': 0, 'goal_difference': 0}
        if away not in table:
            table[away] = {'wins': 0, 'losses': 0, 'draws': 0, 'total_points': 0, 'goal_difference': 0}

        if home_goals > away_goals:
            table[home]['wins'] += 1
            table[home]['total_points'] += 3
            table[home]['goal_difference'] += home_goals - away_goals
        elif home_goals < away_goals:
            table[away]['wins'] += 1
            table[away]['total_points'] += 3
            table[away]['goal_difference'] -= away_goals - home_goals
        else:
            table[home]['draws'] += 1
            table[away]['draws'] += 1
            table[home]['total_points'] += 1
            table[away]['total_points'] += 1

    sorted_table = sorted(table.items(), key=lambda x: (-x[1]['total_points'], -x[1]['goal_difference'], -x[1]['goals_scored'], x[0]))

    return [(team, total_points, goal_difference, goals_scored) for team, stats in sorted_table]
