def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting_orders = []

    for kind, item, quantity in events:
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            if item in stock:
                if stock[item] >= quantity:
                    stock[item] -= quantity
                    waiting_orders.append((item, quantity))
                else:
                    waiting_orders.append((item, stock[item]))
                    stock[item] = 0

    return (stock, waiting_orders)
