def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    """
    Simulates a sandpile on a rectangular grid.

    Parameters:
    - grid: A 2D list of non-negative integers representing the grains in each cell.

    Returns:
    - A new 2D list representing the final state of the sandpile after stabilization.
    - The original grid remains unchanged.
    """
    # Function to check if a cell has more than 3 grains
    def has_more_than_three_grains(cell):
        return sum(cell) > 3

    # Function to perform a single topple operation
    def topple_cell(row, col):
        if has_more_than_three_grains(grid[row][col]):
            grid[row][col] -= 4
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = row + dr, col + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    grid[nr][nc] += 1

    # Perform the stabilization process until no more cells have more than 3 grains
    while True:
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if has_more_than_three_grains(grid[r][c]):
                    topple_cell(r, c)
                    changed = True
        if not changed:
            break

    return grid
```

