def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    current_token = ""
    current_kind = None

    for char in source:
        if char.isalnum() or char == "_":
            current_token += char
        elif char in "+-*/<=>!(),":
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ""
            current_kind = char
        elif char == ".":
            if current_kind == "NUMBER" and current_token[-1].isdigit():
                current_token += "."
            else:
                raise ValueError("Invalid token")
        elif char == "\n" or char == "\t":
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ""
            current_kind = None
        else:
            raise ValueError(f"Invalid character: {char}")

    if current_token:
        tokens.append((current_kind, current_token))

    return tokens
