def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for i in range(len(program)):
        instruction = program[i]
        if instruction == 'PUSH':
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == 'JMP':
            target_index = int(instruction.split()[1])
            if target_index >= len(program):
                raise IndexError("Invalid jump target index")
            i = target_index
        elif instruction == 'JZ':
            if len(stack) < 1:
                raise ValueError("Not enough elements on the stack")
            value = stack.pop()
            if value == 0:
                i = int(instruction.split()[1])
            else:
                i += 1
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
        if i >= len(program):
            break
        if i > 1000:
            raise RuntimeError("Too many instructions executed")
    return stack
```

