```python
def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    current_token = ""
    current_kind = None

    for char in source:
        if char.isdigit():
            current_token += char
            current_kind = "NUMBER"
        elif char.isalpha() or char == "_":
            current_token += char
            current_kind = "NAME"
        elif char in "+-*/<=>=":
            current_token += char
            current_kind = "OP"
        elif char == ".":
            if not current_token:
                raise ValueError("Invalid token")
            current_token += char
            current_kind = "NUMBER"
        elif char == "\n" or char == "\t":
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ""
                current_kind = None
        elif char == "":
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ""
                current_kind = None
        else:
            raise ValueError(f"Invalid character: {char}")

    if current_token:
        tokens.append((current_kind, current_token))

    return tokens
