    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    paths = {node: [] for node in graph}
    distances[start] = 0

    # Priority queue to store nodes to visit
    import heapq
    pq = [(0, start)]

