def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif parts[0] == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif parts[0] == 'SWAP':
            if len(stack) < 2:
