            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack.append(stack.pop() - stack.pop())
        elif parts[0] == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'JMP':
            if not parts[1].isdigit():
                raise ValueError("Invalid jump target")
            return [int(parts[1])]
        elif parts[0] == 'JZ':
            if not parts[1].isdigit():
                raise ValueError("Invalid jump target")
            if stack[-1] == 0:
                return [int(parts[1])]
        elif parts[0] == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    if len(stack) > 1:
        raise ValueError("Stack contains more than one element")
    return stack
