- `DUP`: Duplicate the top element of the stack.
- `SWAP`: Swap the top two elements of the stack.
- `ADD`, `SUB`, or `MUL`: Perform arithmetic operations (`+`, `-`, `*`) on the top two elements of the stack and push the result back onto the stack.
- `JMP t`: Jump to the instruction at index `t`.
- `JZ t`: If the top element of the stack is zero, jump to the instruction at index `t`; otherwise, move to the next instruction.
- `HALT`: Terminate the execution of the program.

The function should handle invalid instructions by raising a `ValueError`. If the number of instructions exceeds 1000, it should raise a `RuntimeError`.

Here's the complete implementation of the `run_stack_machine` function:

```python
def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0

    while ip < len(program):
        instruction = program[ip]

        if instruction == "PUSH":
            n = int(instruction.split()[1])
            stack.append(n)
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements in the stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith("ADD"):
            if len(stack) < 2:
                raise ValueError("Not enough elements in the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction.startswith("SUB"):
            if len(stack) < 2:
                raise ValueError("Not enough elements in the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction.startswith("MUL"):
            if len(stack) < 2:
                raise ValueError("Not enough elements in the stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == "JMP":
            t = int(instruction.split()[1])
            ip = t
        elif instruction == "JZ":
            if stack[-1] == 0:
                t = int(instruction.split()[1])
                ip = t
            else:
                ip += 1
        elif instruction == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        ip += 1

    if ip >= len(program):
        raise RuntimeError("Program terminated without reaching HALT")

    return stack
